_HIERARCHY_AQL = '["PARENT_CHILD", "ATTACHMENT"]'

# A listing query can return a whole connector: one round trip per this many rows
# (the client's default of 1000 made 99k rows cost ~100 cursor fetches).
_KH_V3_BATCH = 50_000

# Seconds before the server kills a check or listing query. Far above what they
# take (a 99k-record flatten reads everything in ~2 s); it bounds a pathological
# graph, and a killed check fails closed (PermissionVerificationUnavailableError).
_KH_V3_QUERY_OPTIONS = {"maxRuntime": 120.0}


def _aql_access_rule(v: str) -> str:
    return f'NOT_NULL({v}.accessRule, "OPEN")'


def _aql_passes_vertex(v: str) -> str:
    """The hop rule without the inheritance probe: what a child needs whether
    or not it inherits."""
    return (f'({_aql_access_rule(v)} IN ["STRICT", "OPEN"]'
            f' OR ({_aql_access_rule(v)} == "RESTRICTED" AND HAS(@granted, {v}._key)))')


def _aql_inherits(child: str, parent: str, tag: str) -> str:
    e = f"kh_ie{tag}"
    return (f"LENGTH(FOR {e} IN {CollectionNames.INHERIT_PERMISSIONS.value} FILTER {e}._from == {child}._id"
            f" AND {e}._to == {parent}._id LIMIT 1 RETURN 1) > 0")


def _aql_granted_hop(child: str, parent: str, tag: str, *, navigation: bool) -> str:
    """One hop of the v3 rule, as Neo4j's ``_kh_v3_granted_hop``; ``kh_opens``
    and ``@granted`` must be in scope. RESTRICTED needs inheritance and its own
    grant, STRICT or OPEN either, any other value nothing.
    ``hideChildren`` is navigation only."""
    rule = _aql_access_rule(child)
    hide = f" AND {parent}.hideChildren != true" if navigation else ""
    granted_open = f'({rule} IN ["STRICT", "OPEN"] AND HAS(@granted, {child}._key))'
    return (f"({child}.isDeleted != true{hide} AND (kh_opens ? true : ({_aql_passes_vertex(child)}"
            f" ? ({granted_open} ? true : {_aql_inherits(child, parent, tag)}) : false)))")


# Arango's write-write conflict (errorNum 1200), as the HTTP client reports it.
_WRITE_CONFLICT = re.compile(r'write-write conflict|"errorNum"\s*:\s*1200\b')


def _aql_hidden_above(v: str, tag: str, *, from_depth: int = 1) -> str:
    """Whether a group that hides its children lies above ``v`` (within the
    walks' 50 hierarchy hops; ``from_depth=0`` counts ``v`` itself)."""
    h, he, hp = f"kh_h{tag}", f"kh_he{tag}", f"kh_hp{tag}"
    return f"""(LENGTH(
        FOR {h}, {he}, {hp} IN {from_depth}..50 INBOUND {v} {CollectionNames.NODE_RELATIONS.value}
            PRUNE {he} != null AND {he}.relationshipType NOT IN {_HIERARCHY_AQL}
            OPTIONS {{uniqueVertices: "path"}}
            FILTER {hp}.edges[*].relationshipType ALL IN {_HIERARCHY_AQL}
            FILTER IS_SAME_COLLECTION("{CollectionNames.RECORD_GROUPS.value}", {h}) AND {h}.hideChildren == true
            LIMIT 1
            RETURN 1) > 0)"""


def _aql_in_hidden_group(v: str, tag: str) -> str:
    """Whether ``v`` belongs to a group that hides its children or lies below
    one: its contents are hidden from listings."""
    og = f"kh_og{tag}"
    return f"""(LENGTH(
        FOR {og} IN 1..1 OUTBOUND {v} {CollectionNames.BELONGS_TO.value}
            FILTER IS_SAME_COLLECTION("{CollectionNames.RECORD_GROUPS.value}", {og})
            FILTER {_aql_hidden_above(og, tag, from_depth=0)}
            LIMIT 1
            RETURN 1) > 0)"""


@dataclass(frozen=True)
class _Visible:
    """What a v3 page lists before its filters: node handles, the groups whose
    records are listed too (a declared scope's), and whether the App's own
    records are (an App that opens everything)."""

    nodes: list[str]
    member_groups: list[str] = field(default_factory=list)
    collection: bool = False


def _kh_v3_ordered(slim: list[list[Any]], descending: bool) -> list[tuple[str, str, str, Any]]:
    """``(id, handle, nodeType, sortKey)`` in ``kh_merge.SortKey`` order: nulls
    last in both directions, the value, then the id ascending. Tuple keys keep
    the sort in C; the order is the comparator's, which the merge re-uses."""
    rows = [(h.split("/", 1)[1], h, node_type, sort_key) for h, node_type, sort_key in slim]
    valued = [r for r in rows if r[3] is not None]
    nulls = sorted((r for r in rows if r[3] is None), key=lambda r: sort_order(r[0]))
    if descending:
        valued.sort(key=lambda r: sort_order(r[0]))
        valued.sort(key=lambda r: sort_order(r[3]), reverse=True)
    else:
        valued.sort(key=lambda r: (sort_order(r[3]), sort_order(r[0])))
    return valued + nulls


def _kh_v3_key(row: tuple[str, str, str, Any], descending: bool):  # noqa: ANN202
    return key_for({"id": row[0], "sortKey": row[3], "nullRank": 1 if row[3] is None else 0}, descending)


# Every folder mimeType as an AQL array, for f-string queries.
_FOLDER_MIMES_AQL = json.dumps(FOLDER_MIME_TYPES)

# Only an org-wide share's edge types grant access through the organization: a
# domain or "anyone" edge left by an older version grants nothing.
_ORG_SHARE_TYPES_AQL = json.dumps(list(ORG_SHARE_PERMISSION_TYPES))


def _aql_grant_edge(grantee: str, edge: str) -> str:
    """Whether PERMISSION edge ``edge`` out of the grantee handle ``grantee`` is a grant."""
    return (f'(NOT STARTS_WITH({grantee}, "{CollectionNames.ORGS.value}/")'
            f" OR {edge}.type IN {_ORG_SHARE_TYPES_AQL})")


def _aql_app_enabled(app: str) -> str:
    """Whether App `app` is open: a KB, or a connector not switched off."""
    return f'({app}.type == "{Connectors.KNOWLEDGE_BASE.value}" OR {app}.isActive != false)'


def _aql_node_type(v: str) -> str:
    """recordGroup, folder or record, as the Neo4j listing decides it."""
    return (f'(IS_SAME_COLLECTION("{CollectionNames.RECORD_GROUPS.value}", {v}) ? "recordGroup"'
            f' : (({v}.mimeType IN {_FOLDER_MIMES_AQL}'
            f' OR UPPER(NOT_NULL({v}.recordType, "")) == "FOLDER") ? "folder" : "record"))')


def _aql_hub_type(v: str) -> str:
    """app, recordGroup, folder or record: the node type the hub reports for a trail
    node or a parent, the same as for a listed row (a folder is a record whose
    mimeType says so, and the collections page acts on "folder")."""
    return f'(IS_SAME_COLLECTION("{CollectionNames.APPS.value}", {v}) ? "app" : {_aql_node_type(v)})'


def _aql_hub_origin(v: str) -> str:
    """COLLECTION for a collection App and everything in one, else CONNECTOR. Read
    from the node, not its stored `origin` (UPLOAD on a collection file), and not
    from a scoping App, which a global search does not have."""
    return (f'((IS_SAME_COLLECTION("{CollectionNames.APPS.value}", {v}) ? {v}.type : {v}.connectorName) == "KB"'
            f' ? "COLLECTION" : "CONNECTOR")')


# Edges one statement moves; a hub node's millions go in batches.
_EDGE_MOVE_BATCH = 5000


# Promotions to these statuses leave the primary with taxonomy to copy to its
# duplicates; see update_queued_duplicates_status.
_RECONCILED_STATUSES = frozenset({ProgressStatus.COMPLETED.value, ProgressStatus.EMPTY.value})


# A record with any of these children waits for them to be purged first.
_CONTAINMENT_RELATIONS = ("PARENT_CHILD", "ATTACHMENT")
# The roots of a connector's delete batches: records in the trash whose parent is
# not in the same batch. A multi-select delete has several. The walk goes through the sparse
# records[connectorId, deletedAtTimestamp] index, which holds only the trash (a
# sparse index serves only conditions that leave null out, hence "> 0"). A
# candidate costs one parent lookup and, for a file organizer, one look for a
# second member of its batch; a deleted folder's files are never counted.
TRASH_LIST_INDEX = "records_connector_deleted_at"
_TRASH_BATCH_ROOTS = f"""
FOR r IN @@records OPTIONS {{ indexHint: "{TRASH_LIST_INDEX}" }}
    FILTER r.connectorId == @connector_id AND r.deletedAtTimestamp > 0
    FILTER r.orgId == @org_id AND r.isDeleted == true AND r.deleteBatchId != null
    LET in_batch_parent = FIRST(
        FOR e IN @@node_relations
            FILTER e._to == r._id AND e.relationshipType IN @containment
            LET p = DOCUMENT(e._from)
            FILTER p != null AND p.isDeleted == true AND p.deleteBatchId == r.deleteBatchId
            LIMIT 1
            RETURN 1
    )
    FILTER in_batch_parent == null
    LET single_file = NOT @single_only OR (
        FIRST(
            FOR e IN @@is_of_type
                FILTER e._from == r._id
                LET t = DOCUMENT(e._to)
                FILTER t != null
                LIMIT 1
                RETURN t.isFile
        ) == true
        AND FIRST(
            FOR x IN @@records
                FILTER x.deleteBatchId == r.deleteBatchId AND x.deleteBatchId != null
                FILTER x._key != r._key AND x.isDeleted == true
                LIMIT 1
                RETURN 1
        ) == null
    )
    FILTER single_file
"""
# records[orgId, deletedAtTimestamp, _key]: one org's trash, in purge order. An
# index with these fields that already exists keeps its own name.
PURGE_WALK_INDEX = "records_org_deleted_at"
_PURGE_WALK_FIELDS = ("orgId", "deletedAtTimestamp", "_key")
# Waiting this long for the purge's exclusive locks means syncs are busy; the next tick tries again.
_PURGE_LOCK_TIMEOUT_SECONDS = 30


class ArangoHTTPProvider(IGraphDBProvider):
    """
    ArangoDB implementation using REST API for fully async operations.

    This provider uses HTTP REST API calls instead of the python-arango SDK
    to avoid blocking the event loop.
    """

    def __init__(
        self,
        logger: Logger,
        config_service: ConfigurationService,
    ) -> None:
        """
        Initialize ArangoDB HTTP provider.

        Args:
            logger: Logger instance
            config_service: Configuration service for database credentials
        """
        self.logger = logger
        self.config_service = config_service
        self.http_client: ArangoHTTPClient | None = None
        # The walk index's actual name, found by its fields (is_trash_walk_index_ready).
        self._purge_walk_index = PURGE_WALK_INDEX
        # Edge collections per graph, read once: see _edge_collections_of_graph.
        self._edge_collections_by_graph: dict[str, list[str]] = {}


        # Connector-specific delete permissions
        self.connector_delete_permissions = {
            Connectors.GOOGLE_DRIVE.value: {
                "allowed_roles": ["OWNER", "WRITER", "FILEORGANIZER"],
                "edge_collections": [
                    CollectionNames.IS_OF_TYPE.value,
                    CollectionNames.NODE_RELATIONS.value,
                    CollectionNames.PERMISSION.value,
                    CollectionNames.USER_DRIVE_RELATION.value,
                    CollectionNames.BELONGS_TO.value,
                    CollectionNames.ANYONE.value
                ],
                "document_collections": [
                    CollectionNames.RECORDS.value,
                    CollectionNames.FILES.value,
                ]
            },
            Connectors.GOOGLE_MAIL.value: {
                "allowed_roles": ["OWNER", "WRITER"],
                "edge_collections": [
                    CollectionNames.IS_OF_TYPE.value,
                    CollectionNames.NODE_RELATIONS.value,
                    CollectionNames.PERMISSION.value,
                    CollectionNames.BELONGS_TO.value,
                ],
                "document_collections": [
                    CollectionNames.RECORDS.value,
                    CollectionNames.MAILS.value,
                    CollectionNames.FILES.value,  # For attachments
                ]
            },
            Connectors.OUTLOOK.value: {
                "allowed_roles": ["OWNER", "WRITER"],
                "edge_collections": [
                    CollectionNames.IS_OF_TYPE.value,
                    CollectionNames.NODE_RELATIONS.value,
                    CollectionNames.PERMISSION.value,
                    CollectionNames.BELONGS_TO.value,
                ],
                "document_collections": [
                    CollectionNames.RECORDS.value,
                    CollectionNames.MAILS.value,
                    CollectionNames.FILES.value,
                ]
            }
        }

        # The per-connector lists predate enrichment edges; a delete through one of
        # them left the record's taxonomy edges behind.
        for spec in self.connector_delete_permissions.values():
            edges = spec["edge_collections"]
            for enrichment_edge in RECORD_ENRICHMENT_EDGE_COLLECTIONS:
                if enrichment_edge not in edges:
                    edges.append(enrichment_edge)

    # ==================== Translation Layer ====================
    # Methods to translate between generic format and ArangoDB-specific format

    def _translate_node_to_arango(self, node: dict) -> dict:
        """
        Translate generic node format to ArangoDB format.

        Converts 'id' field to '_key' for ArangoDB storage.

        Args:
            node: Node in generic format (with 'id' field)

        Returns:
            Node in ArangoDB format (with '_key' field)
        """
        arango_node = node.copy()
        if "id" in arango_node:
            arango_node["_key"] = arango_node.pop("id")
        return arango_node

    def _translate_node_from_arango(self, arango_node: dict) -> dict:
        """
        Translate ArangoDB node to generic format.

        Converts '_key' field to 'id' for generic representation.

        Args:
            arango_node: Node in ArangoDB format (with '_key' field)

        Returns:
            Node in generic format (with 'id' field)
        """
        node = arango_node.copy()
        if "_key" in node:
            node["id"] = node.pop("_key")
        return node

    def _translate_edge_to_arango(self, edge: dict) -> dict:
        """
        Translate generic edge format to ArangoDB format.

        Converts:
        - from_id + from_collection → _from: "collection/id"
        - to_id + to_collection → _to: "collection/id"

        Handles both old format (already has _from/_to) and new generic format
        for backward compatibility during transition.

        Args:
            edge: Edge in generic format

        Returns:
            Edge in ArangoDB format
        """
        arango_edge = edge.copy()

        # Handle new generic format
        if "from_id" in edge and "from_collection" in edge:
            arango_edge["_from"] = f"{edge['from_collection']}/{edge['from_id']}"
            arango_edge.pop("from_id", None)
            arango_edge.pop("from_collection", None)

        if "to_id" in edge and "to_collection" in edge:
            arango_edge["_to"] = f"{edge['to_collection']}/{edge['to_id']}"
            arango_edge.pop("to_id", None)
            arango_edge.pop("to_collection", None)

        # If neither format is present, edge is already in old format (_from/_to)
        # Just return as-is for backward compatibility

        return arango_edge

    def _translate_edge_from_arango(self, arango_edge: dict) -> dict:
        """
        Translate ArangoDB edge to generic format.

        Converts:
        - _from: "collection/id" → from_collection + from_id
        - _to: "collection/id" → to_collection + to_id

        Args:
            arango_edge: Edge in ArangoDB format

        Returns:
            Edge in generic format
        """
        edge = arango_edge.copy()

        if "_from" in edge:
            from_parts = edge["_from"].split("/", 1)
            if len(from_parts) == ARANGO_ID_PARTS_COUNT:
                edge["from_collection"] = from_parts[0]
                edge["from_id"] = from_parts[1]
            edge.pop("_from", None)

        if "_to" in edge:
            to_parts = edge["_to"].split("/", 1)
            if len(to_parts) == ARANGO_ID_PARTS_COUNT:
                edge["to_collection"] = to_parts[0]
                edge["to_id"] = to_parts[1]
            edge.pop("_to", None)

        return edge

    def _translate_nodes_to_arango(self, nodes: list[dict]) -> list[dict]:
        """Batch translate nodes to ArangoDB format."""
        return [self._translate_node_to_arango(node) for node in nodes]

    def _translate_nodes_from_arango(self, arango_nodes: list[dict]) -> list[dict]:
        """Batch translate nodes from ArangoDB format."""
        return [self._translate_node_from_arango(node) for node in arango_nodes]

    def _translate_edges_to_arango(self, edges: list[dict]) -> list[dict]:
        """Batch translate edges to ArangoDB format."""
        return [self._translate_edge_to_arango(edge) for edge in edges]

    def _translate_edges_from_arango(self, arango_edges: list[dict]) -> list[dict]:
        """Batch translate edges from ArangoDB format."""
        return [self._translate_edge_from_arango(edge) for edge in arango_edges]

    # ==================== Connection Management ====================

    async def connect(self) -> bool:
        """
        Connect to ArangoDB via REST API.

        Returns:
            bool: True if connection successful
        """
        try:
            self.logger.info("🚀 Connecting to ArangoDB via HTTP API...")

            # Get ArangoDB configuration
            arangodb_config = await self.config_service.get_config(
                config_node_constants.ARANGODB.value
            )

            if not arangodb_config or not isinstance(arangodb_config, dict):
                raise ValueError("ArangoDB configuration not found or invalid")

            arango_url = str(arangodb_config.get("url"))
            arango_user = str(arangodb_config.get("username"))
            arango_password = str(arangodb_config.get("password"))
            arango_db = str(arangodb_config.get("db"))

            if not all([arango_url, arango_user, arango_password, arango_db]):
                raise ValueError("Missing required ArangoDB configuration values")

            # Create HTTP client
            self.http_client = ArangoHTTPClient(
                base_url=arango_url,
                username=arango_user,
                password=arango_password,
                database=arango_db,
                logger=self.logger
            )

            # Connect to ArangoDB
            if not await self.http_client.connect():
                raise Exception("Failed to connect to ArangoDB")

            # Ensure database exists
            if not await self.http_client.database_exists(arango_db):
                self.logger.info(f"Database '{arango_db}' does not exist, creating it...")
                if not await self.http_client.create_database(arango_db):
                    raise Exception(f"Failed to create database '{arango_db}'")

            self.logger.info("✅ ArangoDB HTTP provider connected successfully")


            # Check if collections exist
            # for collection in CollectionNames:
            #     if await self.http_client.collection_exists(collection.value):
            #         self.logger.info(f"Collection '{collection.value}' exists")

            return True

        except Exception as e:
            self.logger.error(f"❌ Failed to connect to ArangoDB via HTTP: {str(e)}")
            self.http_client = None
            return False

    async def disconnect(self) -> bool:
        """
        Disconnect from ArangoDB.

        Returns:
            bool: True if disconnection successful
        """
        try:
            self.logger.info("🚀 Disconnecting from ArangoDB via HTTP API")
            if self.http_client:
                await self.http_client.disconnect()
            self.http_client = None
            self.logger.info("✅ Disconnected from ArangoDB via HTTP API")
            return True
        except Exception as e:
            self.logger.error(f"❌ Failed to disconnect: {str(e)}")
            return False

    async def ensure_schema(self) -> bool:
        """
        Ensure database schema is initialized (collections, graph, and departments seed).
        Called at startup by the connector and indexing services; idempotent.
        """
        if not self.http_client:
            self.logger.error("Cannot ensure schema: not connected")
            return False

        try:
            self.logger.info("🚀 Ensuring ArangoDB schema (collections, graph, departments)...")

            # Build a lookup: collection name → schema (None means no validation schema)
            schema_by_collection: Dict[str, Any] = {}
            for col_name, col_schema in NODE_COLLECTIONS:
                schema_by_collection[col_name] = col_schema
            for col_name, col_schema in EDGE_COLLECTIONS:
                schema_by_collection[col_name] = col_schema

            # 1. Create all collections (node + edge)
            edge_collection_names = {ed["edge_collection"] for ed in EDGE_DEFINITIONS}
            for col in CollectionNames:
                name = col.value
                is_edge = name in edge_collection_names
                col_schema = schema_by_collection.get(name)
                if not await self.http_client.has_collection(name):
                    if not await self.http_client.create_collection(
                        name, edge=is_edge, schema=col_schema
                    ):
                        self.logger.warning(f"Failed to create collection '{name}', continuing")
                else:
                    self.logger.debug(f"Collection '{name}' already exists")
                    # Ensure schema is applied to pre-existing collections too
                    if col_schema:
                        await self.http_client.update_collection_schema(name, col_schema)

            # 2. Create knowledge graph if it doesn't exist
            has_knowledge = await self.http_client.has_graph(GraphNames.KNOWLEDGE_GRAPH.value)
            if not has_knowledge:
                # Only add edge definitions whose collections exist
                valid_definitions = [
                    ed for ed in EDGE_DEFINITIONS
                    if await self.http_client.has_collection(ed["edge_collection"])
                ]
                if valid_definitions:
                    if not await self.http_client.create_graph(
                        GraphNames.KNOWLEDGE_GRAPH.value,
                        valid_definitions,
                    ):
                        self.logger.warning("Failed to create knowledge graph, continuing")
                else:
                    self.logger.warning("No edge collections found for graph creation")
            else:
                self.logger.info("Knowledge graph already exists, ensuring edge definitions are up to date")
                await self._ensure_edge_definitions_up_to_date(GraphNames.KNOWLEDGE_GRAPH.value)

            # 3. Ensure persistent indexes for frequent query patterns
            await self._ensure_indexes()

            # 4. Seed departments collection with predefined department types
            await self._ensure_departments_seed()

            self.logger.info("✅ ArangoDB schema ensured successfully")
            return True

        except Exception as e:
            self.logger.error(f"❌ Error ensuring schema: {str(e)}")
            return False

    async def _ensure_edge_definitions_up_to_date(self, graph_name: str) -> None:
        """Ensure existing graph edge definitions include all declared vertex collections.

        For each edge definition in EDGE_DEFINITIONS, compare the declared
        ``from_vertex_collections`` and ``to_vertex_collections`` with those
        already registered in the graph. If either declared set has new entries,
        replace the edge definition via the ArangoDB Gharial API so that new
        vertex collections (e.g. artifacts, people) can participate in existing
        edges.

        Both directions matter: comparing only ``to`` silently strands every
        ``from`` addition on already-provisioned databases.
        """
        try:
            graph_info = await self.http_client.get_graph(graph_name)
            if not graph_info:
                return
            existing_defs = graph_info.get("graph", {}).get("edgeDefinitions", [])
            existing_by_collection = {
                ed["collection"]: ed for ed in existing_defs
            }

            for desired in EDGE_DEFINITIONS:
                edge_col = desired["edge_collection"]
                existing = existing_by_collection.get(edge_col)
                if not existing:
                    # An edge collection the graph does not name (one that arrived
                    # under a new name from the rename migration) is invisible to
                    # GRAPH traversals and to delete_nodes_and_edges, which would
                    # leave its edges dangling.
                    url = (
                        f"{self.http_client.base_url}/_db/{self.http_client.database}"
                        f"/_api/gharial/{graph_name}/edge"
                    )
                    payload = {
                        "collection": edge_col,
                        "from": sorted(desired.get("from_vertex_collections", [])),
                        "to": sorted(desired.get("to_vertex_collections", [])),
                    }
                    session = await self.http_client._get_session()
                    async with session.post(url, json=payload) as resp:
                        if resp.status in (200, 201, 202):
                            self.logger.info(
                                "Added edge definition '%s' to graph '%s'",
                                edge_col, graph_name,
                            )
                        elif resp.status == 409:
                            # Already registered by a concurrent starter.
                            self.logger.debug(
                                "Edge definition '%s' already present", edge_col,
                            )
                        else:
                            body = await resp.text()
                            # error, not warning: deletes would silently leave
                            # this collection's edges dangling.
                            self.logger.error(
                                "Could not register edge definition '%s' on graph "
                                "'%s' (%d): %s — traversals and cascading deletes "
                                "will not see this collection",
                                edge_col, graph_name, resp.status, body,
                            )
                    continue
                desired_to = set(desired.get("to_vertex_collections", []))
                existing_to = set(existing.get("to", []))
                desired_from = set(desired.get("from_vertex_collections", []))
                existing_from = set(existing.get("from", []))
                if desired_to.issubset(existing_to) and desired_from.issubset(existing_from):
                    continue

                merged_to = sorted(existing_to | desired_to)
                merged_from = sorted(existing_from | desired_from)
                url = (
                    f"{self.http_client.base_url}/_db/{self.http_client.database}"
                    f"/_api/gharial/{graph_name}/edge/{edge_col}"
                )
                payload = {"collection": edge_col, "from": merged_from, "to": merged_to}
                session = await self.http_client._get_session()
                async with session.put(url, json=payload) as resp:
                    if resp.status in (200, 201, 202):
                        self.logger.debug(
                            "Updated edge definition '%s': from=%s to=%s",
                            edge_col, merged_from, merged_to,
                        )
                    else:
                        body = await resp.text()
                        self.logger.warning(
                            "Failed to update edge definition '%s' (%d): %s",
                            edge_col, resp.status, body,
                        )
        except Exception as e:
            self.logger.warning("Edge definition migration failed (non-fatal): %s", e)

    async def _ensure_indexes(self) -> None:
        """Create persistent indexes for frequent query patterns.

        Indexes are built here: each call to ensure_persistent_index() creates (or ensures)
        the index via the ArangoDB HTTP API (see arango_http_client.ensure_persistent_index).

        Edge collections have automatic indexes on _from and _to fields which optimize
        graph traversals. Custom indexes below cover document-lookup hot paths.
        """
        # ==================== TAXONOMY INDEXES ====================
        # Entity resolution looks canonical category/subcategory/topic/language
        # nodes up by (orgId, normalizedName) once per record — see
        # app.modules.entity_resolution and find_taxonomy_nodes().
        for taxonomy_collection in sorted(TAXONOMY_COLLECTIONS):
            await self.http_client.ensure_persistent_index(
                taxonomy_collection,
                ["orgId", "normalizedName"],
            )
            await self.http_client.ensure_persistent_index(
                taxonomy_collection,
                ["orgId", "normalizedAliases[*]"],
            )

        # ==================== ENTITY INDEX SOURCES ====================
        # The entity index rebuild pages each source by scope, then key; without
        # _key trailing the scope every page re-sorts the whole scope. Records'
        # (connectorId, _key) is created below.
        for spec in ENTITY_INDEX_SOURCES.values():
            if spec.collection != CollectionNames.RECORDS.value:
                await self.http_client.ensure_persistent_index(
                    spec.collection, [spec.scope_field, "_key"],
                )

        # ==================== RECORD INDEXES (Highest Priority) ====================
        # Records are the most queried entity, especially in permission checks

        # COMPOSITE: virtualRecordId + orgId
        # Pattern: FOR record IN records FILTER record.virtualRecordId IN @ids AND record.orgId == @orgId
        # Used in: get_records_by_virtual_record_ids (Phase 3 batch fetch after Qdrant search)
        await self.http_client.ensure_persistent_index(
            CollectionNames.RECORDS.value,
            ["virtualRecordId", "orgId"],
        )

        # COMPOSITE: externalRecordId + connectorId (ALWAYS queried together)
        # Pattern: FOR record IN records FILTER record.externalRecordId == @id AND record.connectorId == @cid
        await self.http_client.ensure_persistent_index(
            CollectionNames.RECORDS.value,
            ["externalRecordId", "connectorId"],
        )

        # SINGLE: orgId (queried independently and with other fields)
        await self.http_client.ensure_persistent_index(
            CollectionNames.RECORDS.value,
            ["orgId"],
        )

        # COMPOSITE: webUrl + orgId (URL-based record lookup, get_record_by_weburl)
        await self.http_client.ensure_persistent_index(
            CollectionNames.RECORDS.value,
            ["webUrl", "orgId"],
        )

        # SINGLE: connectorId (queried independently in many patterns)
        await self.http_client.ensure_persistent_index(
            CollectionNames.RECORDS.value,
            ["connectorId"],
        )

        # COMPOUND: the vector-membership backfill keyset walk filters on
        # connectorId then sorts by _key. Same reasoning as the reindex compound
        # below — without _key trailing the filter field the SORT is not
        # index-satisfied and every page re-sorts the connector's whole record set.
        await self.http_client.ensure_persistent_index(
            CollectionNames.RECORDS.value,
            ["connectorId", "_key"],
        )

        # SINGLE: indexingStatus (pipeline queries)
        await self.http_client.ensure_persistent_index(
            CollectionNames.RECORDS.value,
            ["indexingStatus"],
        )

        # SINGLE: duplicateReconcilePending. The reconcile retry sweep looks for
        # the few records with it set; unindexed that is a full scan per tick.
        await self.http_client.ensure_persistent_index(
            CollectionNames.RECORDS.value,
            ["duplicateReconcilePending", "duplicateReconcileDueAt"],
        )

        # COMPOUND: the reindex keyset walk filters on all three then sorts by _key.
        # Without _key trailing the filter fields the SORT is not index-satisfied and
        # every batch re-sorts the whole candidate set.
        await self.http_client.ensure_persistent_index(
            CollectionNames.RECORDS.value,
            ["orgId", "connectorId", "indexingStatus", "_key"],
        )

        # SINGLE: origin (heavily used in permission WHERE clauses)
        await self.http_client.ensure_persistent_index(
            CollectionNames.RECORDS.value,
            ["origin"],
        )

        # SINGLE: md5Checksum (duplicate detection)
        await self.http_client.ensure_persistent_index(
            CollectionNames.RECORDS.value,
            ["md5Checksum"],
        )

        # SPARSE: only trashed records carry deletedAtTimestamp, so the index
        # holds just the trash and gives the purge a sorted keyset walk.
        await self.http_client.ensure_persistent_index(
            CollectionNames.RECORDS.value,
            ["deletedAtTimestamp", "_key"],
            sparse=True,
        )

        # COMPOSITE: the purge's walk of one org's trash, in (deletedAtTimestamp,
        # _key) order, one page of index entries per page. Not sparse: 3.12
        # cannot serve a range from a sparse index that ends in _key. Live
        # records hold null here, which sorts before every timestamp. Hinted by
        # name; without it the planner took the orgId index and sorted every
        # record of the org on each page.
        await self.http_client.ensure_persistent_index(
            CollectionNames.RECORDS.value,
            list(_PURGE_WALK_FIELDS),
            name=PURGE_WALK_INDEX,
        )

        # SPARSE: restore reads a whole delete batch; the field is cleared on
        # restore, so only the trash is in it.
        await self.http_client.ensure_persistent_index(
            CollectionNames.RECORDS.value,
            ["deleteBatchId"],
            sparse=True,
        )

        # SPARSE: a collection's Recently deleted list, newest first. Only the
        # trash has deletedAtTimestamp, so only the trash is in it.
        await self.http_client.ensure_persistent_index(
            CollectionNames.RECORDS.value,
            ["connectorId", "deletedAtTimestamp"],
            sparse=True,
            name=TRASH_LIST_INDEX,
        )

        # COMPOSITE: orgId + recordType — gallery listing filters ARTIFACT
        # records after the permission-edge walk.
        await self.http_client.ensure_persistent_index(
            CollectionNames.RECORDS.value,
            ["orgId", "recordType"],
        )

        # COMPOSITE: orgId + visibility — user-facing artifact display policy.
        await self.http_client.ensure_persistent_index(
            CollectionNames.ARTIFACTS.value,
            ["orgId", "visibility"],
        )

        # COMPOSITE: orgId + conversationId — conversation-scoped artifact lookup
        # (registry list_for_conversation and gallery conversation filter).
        await self.http_client.ensure_persistent_index(
            CollectionNames.ARTIFACTS.value,
            ["orgId", "conversationId"],
        )

        # ==================== USER INDEXES (High Priority) ====================

        # SINGLE: email (authentication, lookups)
        await self.http_client.ensure_persistent_index(
            CollectionNames.USERS.value,
            ["email"],
        )

        # SINGLE: userId (user identification)
        await self.http_client.ensure_persistent_index(
            CollectionNames.USERS.value,
            ["userId"],
        )

        # SINGLE: orgId (org-scoped queries)
        await self.http_client.ensure_persistent_index(
            CollectionNames.USERS.value,
            ["orgId"],
        )

        # ==================== RECORDGROUP INDEXES (High Priority) ====================

        # COMPOSITE: externalGroupId + connectorId (ALWAYS queried together)
        # Pattern: FOR rg IN record_groups FILTER rg.externalGroupId == @id AND rg.connectorId == @cid
        await self.http_client.ensure_persistent_index(
            CollectionNames.RECORD_GROUPS.value,
            ["externalGroupId", "connectorId"],
        )

        # SINGLE: orgId (org-scoped queries)
        await self.http_client.ensure_persistent_index(
            CollectionNames.RECORD_GROUPS.value,
            ["orgId"],
        )

        # SINGLE: connectorId (cleanup operations, queried independently)
        await self.http_client.ensure_persistent_index(
            CollectionNames.RECORD_GROUPS.value,
            ["connectorId"],
        )

        # SINGLE: groupType (KB filtering)
        await self.http_client.ensure_persistent_index(
            CollectionNames.RECORD_GROUPS.value,
            ["groupType"],
        )

        # ==================== AGENT SKILLS INDEXES ====================

        # COMPOSITE: orgId + status — GraphSkillStore.list_skills's hot path
        # (catalog refresh per SkillManager.start()/refresh()).
        await self.http_client.ensure_persistent_index(
            CollectionNames.AGENT_SKILLS.value,
            ["orgId", "status"],
        )

        # SINGLE: name — get_skill/exists/create's uniqueness-within-org lookup.
        await self.http_client.ensure_persistent_index(
            CollectionNames.AGENT_SKILLS.value,
            ["orgId", "name"],
        )

        # COMPOSITE: skillKey + version — GraphSkillStore.get_version lookup.
        await self.http_client.ensure_persistent_index(
            CollectionNames.AGENT_SKILL_VERSIONS.value,
            ["skillKey", "version"],
        )

        # SINGLE: orgId — GraphSkillStore candidate queue listing.
        await self.http_client.ensure_persistent_index(
            CollectionNames.AGENT_SKILL_CANDIDATES.value,
            ["orgId"],
        )

        # ==================== PEOPLE INDEXES ====================

        # UNIQUE: (orgId, email) — the business key for a Person, and load-bearing
        # rather than merely defensive. upsert_person_by_email is a read-then-write
        # UPSERT, which ArangoDB does not make atomic on its own; concurrent syncs
        # resolving the same external collaborator in the same org would each insert
        # without this index to serialise them.
        # Composite, not email-only: the same email can legitimately exist once per
        # org (D1 revisited — Person is now org-scoped like User).
        # Returns False (logged, non-fatal) on a collection that already holds
        # duplicates — dedupe those before the guarantee applies.
        await self.http_client.ensure_persistent_index(
            CollectionNames.PEOPLE.value,
            ["orgId", "email"],
            unique=True,
        )

    async def _ensure_departments_seed(self) -> None:
        """Initialize departments collection with predefined department types if missing."""
        try:
            existing = await self.execute_query(
                # Only global ones: an org's own department of the same name
                # must not stop the global one being seeded.
                f"FOR d IN {CollectionNames.DEPARTMENTS.value} FILTER d.orgId == null RETURN d.departmentName",
                {},
            )
            existing_names = set() if not existing else {r for r in existing if r is not None}

            new_departments = [
                {"id": global_department_key(dept.value), "departmentName": dept.value, "orgId": None}
                for dept in DepartmentNames
                if dept.value not in existing_names
            ]

            if new_departments:
                self.logger.info(f"🚀 Inserting {len(new_departments)} department(s)")
                await self.batch_upsert_nodes(
                    new_departments,
                    CollectionNames.DEPARTMENTS.value,
                )
                self.logger.info("✅ Departments seed completed")
        except Exception as e:
            self.logger.warning(f"Departments seed failed (non-fatal): {str(e)}")

    # ==================== Transaction Management ====================

    async def begin_transaction(self, read: list[str], write: list[str], explicit: bool | None = None) -> str:
        """
        Begin a database transaction - FULLY ASYNC.

        Args:
            read: Collections to read from
            write: Collections to write to
            explicit: not read; a transaction here is always a real one

        Returns:
            str: Transaction ID (e.g., "123456789")
        """
        try:
            return await self.http_client.begin_transaction(read, write)
        except Exception as e:
            self.logger.error(f"❌ Failed to begin transaction: {str(e)}")
            raise

    async def commit_transaction(self, transaction: str) -> None:
        """
        Commit a transaction - FULLY ASYNC.

        Args:
            transaction: Transaction ID (string)
        """
        try:
            await self.http_client.commit_transaction(transaction)
        except Exception as e:
            self.logger.error(f"❌ Failed to commit transaction: {str(e)}")
            raise

    def is_transient_error(self, error: BaseException) -> bool:
        """A write-write conflict (errorNum 1200) with another writer, such as
        indexing updating the same record. A stream transaction rolls back
        whole, so the block can be re-run."""
        return isinstance(error, Exception) and _is_write_conflict(error)

    def is_write_conflict(self, error: BaseException) -> bool:
        return self.is_transient_error(error)

    async def rollback_transaction(self, transaction: str) -> None:
        """
        Rollback a transaction - FULLY ASYNC.

        Args:
            transaction: Transaction ID (string)
        """
        try:
            await self.http_client.abort_transaction(transaction)
        except Exception as e:
            self.logger.error(f"❌ Failed to rollback transaction: {str(e)}")
            raise

    # ==================== Document Operations ====================

    async def get_document(
        self,
        document_key: str,
        collection: str,
        transaction: str | None = None,
        *,
        raise_on_error: bool = False,
    ) -> dict | None:
        """
        Get a document by key - FULLY ASYNC.

        Args:
            document_key: Document key (generic 'id')
            collection: Collection name
            transaction: Optional transaction ID
            raise_on_error: Propagate the failure instead of answering None.

        Returns:
            Optional[Dict]: Document data in generic format (with 'id' field) or None
        """
        try:
            doc = await self.http_client.get_document(
                collection,
                document_key,
                txn_id=transaction,
                # The client answers None for a 404, a 503 and a dead connection
                # alike, so the flag has to reach it; stopping at this method
                # leaves the `raise` below unreachable on ArangoDB.
                raise_on_error=raise_on_error,
            )
            if doc:
                # Translate from ArangoDB format to generic format
                return self._translate_node_from_arango(doc)
            return None
        except Exception as e:
            self.logger.error(f"❌ Failed to get document: {str(e)}")
            if raise_on_error:
                raise
            return None

    async def get_record_by_id(
        self,
        record_id: str,
        transaction: str | None = None,
    ) -> Record | None:
        """
        Get record by internal ID (_key) with associated type document (file/mail/etc.).

        Args:
            record_id: Internal record ID (_key)
            transaction: Optional transaction ID

        Returns:
            Optional[Record]: Typed Record instance (FileRecord, MailRecord, etc.) or None
        """
        try:
            query = f"""
            FOR record IN {CollectionNames.RECORDS.value}
                FILTER record._key == @id
                LET typeDoc = (
                    FOR edge IN {CollectionNames.IS_OF_TYPE.value}
                        FILTER edge._from == record._id
                        LET doc = DOCUMENT(edge._to)
                        FILTER doc != null
                        RETURN doc
                )[0]
                RETURN {{
                    record: record,
                    typeDoc: typeDoc
                }}
            """
            results = await self.execute_query(
                query,
                bind_vars={"id": record_id},
                transaction=transaction,
            )
            if not results:
                return None
            result = results[0]
            return self._create_typed_record_from_arango(
                result["record"],
                result.get("typeDoc"),
            )
        except Exception as e:
            self.logger.error("❌ Failed to get record by id %s: %s", record_id, str(e))
            return None

    async def get_typed_records_batch(
        self,
        record_ids: list[str],
    ) -> dict[str, Record]:
        """
        Batch-fetch typed Record instances for the given record IDs.

        Args:
            record_ids: Internal record IDs (_key)

        Returns:
            dict[str, Record]: Mapping of record ID to typed Record instance.
            IDs not found or failing typed construction are silently omitted.
        """
        if not record_ids:
            return {}
        try:
            query = f"""
            FOR record IN {CollectionNames.RECORDS.value}
                FILTER record._key IN @record_ids
                LET typeDoc = (
                    FOR edge IN {CollectionNames.IS_OF_TYPE.value}
                        FILTER edge._from == record._id
                        LET doc = DOCUMENT(edge._to)
                        FILTER doc != null
                        RETURN doc
                )[0]
                RETURN {{
                    id: record._key,
                    record: record,
                    typeDoc: typeDoc
                }}
            """
            results = await self.execute_query(query, bind_vars={"record_ids": record_ids})
            typed: dict[str, Record] = {}
            for row in results or []:
                try:
                    typed[row["id"]] = self._create_typed_record_from_arango(
                        row["record"], row.get("typeDoc")
                    )
                except Exception:
                    continue
            return typed
        except Exception as e:
            self.logger.warning("get_typed_records_batch failed: %s", str(e))
            return {}

    async def get_node_depths_batch(
        self,
        parent_id: str,
        node_ids: list[str],
        max_depth: int = 3,
        parent_type: str | None = None,
    ) -> dict[str, int]:
        if not node_ids:
            return {}
        safe_depth = max(1, min(int(max_depth), 10))
        try:
            if parent_type == "app":
                record_depth = max(1, safe_depth - 1)
                query = f"""
                LET rg_ids = (
                    FOR rg IN {CollectionNames.RECORD_GROUPS.value}
                        FILTER rg.connectorId == @parent_id
                        FILTER rg.isDeleted != true
                        RETURN rg._id
                )
                LET rg_direct_ids = (
                    FOR rg_id IN rg_ids
                        FOR v IN 1..1 INBOUND rg_id {CollectionNames.BELONGS_TO.value}
                            FILTER IS_SAME_COLLECTION("records", v)
                            FILTER v._key IN @node_ids
                            RETURN v._key
                )
                LET kb_direct_ids = (
                    FOR edge IN {CollectionNames.BELONGS_TO.value}
                        FILTER edge._to == CONCAT("apps/", @parent_id)
                        FILTER STARTS_WITH(edge._from, "records/")
                        LET rec = DOCUMENT(edge._from)
                        FILTER rec != null AND rec.isDeleted != true
                        FILTER rec._key IN @node_ids
                        RETURN rec._key
                )
                LET direct_ids = UNION_DISTINCT(rg_direct_ids, kb_direct_ids)
                LET deeper = (
                    FOR rg_id IN rg_ids
                        FOR top IN 1..1 INBOUND rg_id {CollectionNames.BELONGS_TO.value}
                            FILTER IS_SAME_COLLECTION("records", top)
                            FOR v, e, p IN 1..{record_depth} OUTBOUND top {CollectionNames.NODE_RELATIONS.value}
                                OPTIONS {{bfs: true, uniqueVertices: "global"}}
                                FILTER p.edges[*].relationshipType ALL IN ["PARENT_CHILD", "ATTACHMENT"]
                                FILTER v._key IN @node_ids
                                RETURN {{id: v._key, level: LENGTH(p.edges) + 1}}
                )
                RETURN APPEND(
                    (FOR d IN direct_ids RETURN {{id: d, level: 1}}),
                    deeper
                )
                """
                raw = await self.execute_query(
                    query, bind_vars={"parent_id": parent_id, "node_ids": node_ids}
                )
                results = raw[0] if raw else []
            elif parent_type == "recordGroup":
                record_depth = max(1, safe_depth - 1)
                query = f"""
                LET rg_doc_id = CONCAT("{CollectionNames.RECORD_GROUPS.value}/", @parent_id)
                LET direct_ids = (
                    FOR v IN 1..1 INBOUND rg_doc_id {CollectionNames.BELONGS_TO.value}
                        FILTER IS_SAME_COLLECTION("records", v)
                        FILTER v._key IN @node_ids
                        RETURN v._key
                )
                LET deeper = (
                    FOR top IN 1..1 INBOUND rg_doc_id {CollectionNames.BELONGS_TO.value}
                        FILTER IS_SAME_COLLECTION("records", top)
                        FOR v, e, p IN 1..{record_depth} OUTBOUND top {CollectionNames.NODE_RELATIONS.value}
                            OPTIONS {{bfs: true, uniqueVertices: "global"}}
                            FILTER p.edges[*].relationshipType ALL IN ["PARENT_CHILD", "ATTACHMENT"]
                            FILTER v._key IN @node_ids
                            RETURN {{id: v._key, level: LENGTH(p.edges) + 1}}
                )
                RETURN APPEND(
                    (FOR d IN direct_ids RETURN {{id: d, level: 1}}),
                    deeper
                )
                """
                raw = await self.execute_query(
                    query, bind_vars={"parent_id": parent_id, "node_ids": node_ids}
                )
                results = raw[0] if raw else []
            else:
                query = f"""
                LET parent = DOCUMENT(CONCAT("records/", @parent_id))
                FILTER parent != null
                FOR v, e, p IN 1..{safe_depth} OUTBOUND parent {CollectionNames.NODE_RELATIONS.value}
                    OPTIONS {{bfs: true, uniqueVertices: "global"}}
                    FILTER p.edges[*].relationshipType ALL IN ["PARENT_CHILD", "ATTACHMENT"]
                    FILTER v._key IN @node_ids
                    RETURN {{id: v._key, level: LENGTH(p.edges)}}
                """
                results = await self.execute_query(
                    query, bind_vars={"parent_id": parent_id, "node_ids": node_ids}
                )
            depth_map: dict[str, int] = {}
            for row in results or []:
                rid, lvl = row["id"], row["level"]
                if rid not in depth_map or lvl < depth_map[rid]:
                    depth_map[rid] = lvl
            return depth_map
        except Exception as e:
            self.logger.error(f"get_node_depths_batch failed: {e}")
            return {}

    # ==================== Connector Registry Operations ====================

    async def check_connector_name_exists(
        self,
        collection: str,
        instance_name: str,
        scope: str,
        org_id: str | None = None,
        user_id: str | None = None,
        transaction: str | None = None,
        exclude_connector_id: str | None = None,
    ) -> bool:
        """Check if a connector instance name already exists for the given scope."""
        try:
            normalized_name = instance_name.strip().lower()
            # Arango rejects bind variables a query does not reference.
            exclude_filter = "FILTER doc._key != @exclude_key" if exclude_connector_id else ""

            if scope == "personal":
                query = f"""
                FOR doc IN @@collection
                    FILTER doc.scope == @scope
                    FILTER doc.createdBy == @user_id
                    FILTER LOWER(TRIM(doc.name)) == @normalized_name
                    {exclude_filter}
                    LIMIT 1
                    RETURN doc._key
                """
                bind_vars = {
                    "@collection": collection,
                    "scope": scope,
                    "user_id": user_id,
                    "normalized_name": normalized_name,
                }
            else:  # team scope
                query = f"""
                FOR edge IN @@edge_collection
                    FILTER edge._from == @org_id
                    FOR doc IN @@collection
                        FILTER doc._id == edge._to
                        FILTER doc.scope == @scope
                        FILTER LOWER(TRIM(doc.name)) == @normalized_name
                        {exclude_filter}
                        LIMIT 1
                        RETURN doc._key
                """
                bind_vars = {
                    "@collection": collection,
                    "@edge_collection": CollectionNames.ORG_APP_RELATION.value,
                    "org_id": f"{CollectionNames.ORGS.value}/{org_id}",
                    "scope": scope,
                    "normalized_name": normalized_name,
                }

            if exclude_connector_id:
                bind_vars["exclude_key"] = exclude_connector_id

            results = await self.execute_query(query, bind_vars=bind_vars, transaction=transaction)
            return len(results) > 0

        except Exception as e:
            self.logger.error(f"Failed to check connector name exists: {e}")
            return False

    async def batch_update_connector_status(
        self,
        collection: str,
        connector_keys: list[str],
        *,
        is_active: bool,
        is_agent_active: bool,
        transaction: str | None = None,
    ) -> int:
        """Batch update isActive and isAgentActive status for multiple connectors."""
        try:
            if not connector_keys:
                return 0

            current_timestamp = get_epoch_timestamp_in_ms()

            query = """
            FOR doc IN @@collection
                FILTER doc._key IN @keys
                UPDATE doc WITH {
                    isActive: @is_active,
                    isAgentActive: @is_agent_active,
                    updatedAtTimestamp: @timestamp
                } IN @@collection
                RETURN NEW
            """
            bind_vars = {
                "@collection": collection,
                "keys": connector_keys,
                "is_active": is_active,
                "is_agent_active": is_agent_active,
                "timestamp": current_timestamp,
            }
            results = await self.execute_query(query, bind_vars=bind_vars, transaction=transaction)
            return len(results)

        except Exception as e:
            self.logger.error(f"Failed to batch update connector status: {e}")
            return 0

    async def normalize_folder_mime_types(self, batch_size: int = 1000) -> dict:
        """See the interface. One scan for the folder records to rewrite, then
        batches, then a check that none is left, so a partial run leaves the flag
        unset. Plain queries: a stream transaction has no intermediate commits."""
        mismatch = """
            FOR f IN @@files
                FILTER f.isFile == false
                FOR r IN 1..1 INBOUND f @@is_of_type
                    FILTER IS_SAME_COLLECTION(@records, r) AND r.mimeType != @folder"""
        bind = {
            "@files": CollectionNames.FILES.value,
            "@is_of_type": CollectionNames.IS_OF_TYPE.value,
            "records": CollectionNames.RECORDS.value,
            "folder": MimeTypes.FOLDER.value,
        }
        keys = await self.http_client.execute_aql(f"{mismatch} RETURN DISTINCT r._key", bind) or []
        normalized = 0
        for i in range(0, len(keys), batch_size):
            rows = await self.http_client.execute_aql(
                """
                FOR r IN @@records
                    FILTER r._key IN @keys
                    UPDATE r WITH {mimeType: @folder} IN @@records
                    RETURN 1
                """,
                {"@records": CollectionNames.RECORDS.value, "keys": keys[i:i + batch_size],
                 "folder": MimeTypes.FOLDER.value},
            )
            normalized += len(rows or [])
        left = await self.http_client.execute_aql(f"RETURN LENGTH({mismatch} LIMIT 1 RETURN 1)", bind)
        if left and left[0]:
            raise RuntimeError("Folder records still carry another mimeType after the rewrite")
        return {"normalized": normalized}

    # A hierarchy parent that still exists: an edge left pointing from a removed
    # document (the KB apps migration removes the old KB groups) is no parent.
    # Parenthesised: AQL's NOT binds tighter than ">", so NOT LENGTH(...) > 0 would
    # read (NOT LENGTH(...)) > 0 and never hold.
    _BACKFILL_HAS_PARENT = """(LENGTH(FOR h IN @@nr FILTER h._to == {v} AND h.relationshipType IN @hierarchy
                                  AND DOCUMENT(h._from) != null LIMIT 1 RETURN 1) > 0)"""

    # Each shape yields (parent handle, child handle) and is re-checked when written,
    # so a sync that ran in between is not undone; see backfill_hierarchy.
    _BACKFILL_PAIRS = {
        "collection_roots": """
            FOR app IN @@apps FILTER app.type == "KB"
                FOR r IN 1..1 INBOUND app @@belongs_to
                    FILTER IS_SAME_COLLECTION("records", r) AND r.isDeleted != true AND r.externalParentId == null
                    FILTER NOT {has_parent_r}
                    RETURN DISTINCT [app._id, r._id]""",
        "groups": """
            FOR g IN @@groups FILTER g.connectorId != null
                FILTER NOT {has_parent_g}
                LET parent = FIRST(FOR p IN 1..1 OUTBOUND g @@belongs_to
                                   FILTER IS_SAME_COLLECTION("recordGroups", p) RETURN p._id)
                LET app = FIRST(FOR a IN 1..1 OUTBOUND g @@belongs_to
                                FILTER IS_SAME_COLLECTION("apps", a) RETURN a._id)
                LET from = parent != null ? parent : app
                FILTER from != null
                RETURN DISTINCT [from, g._id]""",
        # The record's own group, or its only one; a record in several groups with
        # no own group named (a Shared-with-Me copy) is left for the next sync.
        "group_roots": """
            FOR r IN @@records
                FILTER r.isDeleted != true AND r.externalParentId == null
                FILTER NOT {has_parent_r}
                LET groups = (FOR g IN 1..1 OUTBOUND r @@belongs_to
                              FILTER IS_SAME_COLLECTION("recordGroups", g) RETURN g._key)
                LET own = r.recordGroupId IN groups ? r.recordGroupId : (LENGTH(groups) == 1 ? groups[0] : null)
                FILTER own != null
                RETURN DISTINCT [CONCAT("recordGroups/", own), r._id]""",
        # Only where nobody holds a grant on the parent record or a record above it:
        # the older model gave a nested record to its group's principals alone, so
        # inheriting from a granted parent would open it to that parent's grantees too.
        # The parent must inherit from one of the child's own groups: a parent in
        # another group (a story under a cross-project epic) would hand the child
        # to that group's audience.
        "nested_inheritance": """
            FOR h IN @@nr
                FILTER h.relationshipType IN @hierarchy
                FILTER IS_SAME_COLLECTION("records", h._from) AND IS_SAME_COLLECTION("records", h._to)
                FILTER DOCUMENT(h._from) != null
                LET child_groups = (FOR i IN @@ip FILTER i._from == h._to
                                    AND IS_SAME_COLLECTION("recordGroups", i._to) RETURN i._to)
                FILTER LENGTH(child_groups) > 0
                FILTER LENGTH(FOR i IN @@ip FILTER i._from == h._from AND i._to IN child_groups
                              LIMIT 1 RETURN 1) > 0
                FILTER LENGTH(FOR i IN @@ip FILTER i._from == h._to AND i._to == h._from LIMIT 1 RETURN 1) == 0
                FILTER LENGTH(
                    FOR a, e IN 0..50 INBOUND h._from @@nr
                        PRUNE e != null AND (e.relationshipType NOT IN @hierarchy OR !IS_SAME_COLLECTION("records", a))
                        OPTIONS {uniqueVertices: "path"}
                        // PRUNE still emits the vertex it stops at: only a hierarchy edge counts.
                        FILTER e == null OR e.relationshipType IN @hierarchy
                        FILTER IS_SAME_COLLECTION("records", a)
                        FILTER LENGTH(FOR p IN @@perm FILTER p._to == a._id LIMIT 1 RETURN 1) > 0
                        LIMIT 1 RETURN 1) == 0
                RETURN DISTINCT [h._from, h._to]""",
        # A record nested under a record of another group inherits from its own
        # group, which no hierarchy edge reaches it from: it hangs off that group too.
        # A parent record inside the group makes the child nested_inheritance's.
        "cross_group_children": """
            FOR own IN @@ip
                FILTER IS_SAME_COLLECTION("records", own._from) AND IS_SAME_COLLECTION("recordGroups", own._to)
                LET parents = (FOR h IN @@nr
                                   FILTER h._to == own._from AND h.relationshipType IN @hierarchy
                                   FILTER IS_SAME_COLLECTION("records", h._from) AND DOCUMENT(h._from) != null
                                   RETURN h._from)
                FILTER LENGTH(parents) > 0
                FILTER LENGTH(FOR pr IN parents
                                  FILTER LENGTH(FOR i IN @@ip
                                                    FILTER i._from == pr AND i._to == own._to
                                                    LIMIT 1 RETURN 1) > 0
                                      OR LENGTH(FOR b IN @@belongs_to
                                                    FILTER b._from == pr AND b._to == own._to
                                                    LIMIT 1 RETURN 1) > 0
                                  LIMIT 1 RETURN 1) == 0
                FILTER LENGTH(FOR b IN @@belongs_to
                                  FILTER b._from == own._from AND b._to == own._to
                                  LIMIT 1 RETURN 1) > 0
                FILTER LENGTH(FOR h IN @@nr
                                  FILTER h._from == own._to AND h._to == own._from AND h.relationshipType IN @hierarchy
                                  LIMIT 1 RETURN 1) == 0
                LET child = DOCUMENT(own._from)
                FILTER child != null AND child.isDeleted != true AND DOCUMENT(own._to) != null
                RETURN DISTINCT [own._to, own._from]""",
        # A nested record nested_inheritance left to its group (a grant above it)
        # inherits from no hierarchy parent, so no walk reaches it: it hangs off
        # that group, which gives it main's audience, until a sync re-parents it.
        "nested_group_roots": """
            FOR inh IN @@ip
                FILTER IS_SAME_COLLECTION("records", inh._from) AND IS_SAME_COLLECTION("recordGroups", inh._to)
                LET child = DOCUMENT(inh._from)
                LET grp = DOCUMENT(inh._to)
                FILTER child != null AND child.isDeleted != true AND grp != null
                    AND IS_STRING(child.connectorId) AND grp.connectorId == child.connectorId
                // An App that opens its records lists the child under its parent already.
                LET app = DOCUMENT(CONCAT("apps/", child.connectorId))
                FILTER app != null AND app.permissionModel != "APP_LEVEL" AND app.type != "KB"
                LET parents = (FOR h IN @@nr
                                   FILTER h._to == inh._from AND h.relationshipType IN @hierarchy
                                   FILTER DOCUMENT(h._from) != null
                                   RETURN h._from)
                FILTER LENGTH(parents[* FILTER IS_SAME_COLLECTION("records", CURRENT)]) > 0
                FILTER LENGTH(FOR pr IN parents
                                  FILTER LENGTH(FOR i IN @@ip
                                                    FILTER i._from == inh._from AND i._to == pr
                                                    LIMIT 1 RETURN 1) > 0
                                  LIMIT 1 RETURN 1) == 0
                RETURN DISTINCT [inh._to, inh._from]""",
    }

    # Re-checked per pair at write time (child handle is pr[1]).
    _BACKFILL_RECHECK = {
        "collection_roots": "LET r = DOCUMENT(pr[1]) FILTER r != null AND r.externalParentId == null AND NOT {has_parent}",
        "groups": "FILTER DOCUMENT(pr[1]) != null AND NOT {has_parent}",
        "group_roots": "LET r = DOCUMENT(pr[1]) FILTER r != null AND r.externalParentId == null AND NOT {has_parent}",
        "cross_group_children": (
            "FILTER DOCUMENT(pr[1]) != null AND LENGTH(FOR h IN @@nr"
            " FILTER h._from == pr[0] AND h._to == pr[1] AND h.relationshipType IN @hierarchy"
            " LIMIT 1 RETURN 1) == 0"
        ),
        # A sync in between may have re-parented the child and dropped its group inheritance.
        "nested_group_roots": (
            "FILTER DOCUMENT(pr[1]) != null"
            " AND LENGTH(FOR i IN @@ip FILTER i._from == pr[1] AND i._to == pr[0] LIMIT 1 RETURN 1) > 0"
            " AND LENGTH(FOR h IN @@nr"
            " FILTER h._from == pr[0] AND h._to == pr[1] AND h.relationshipType IN @hierarchy"
            " LIMIT 1 RETURN 1) == 0"
        ),
    }

    async def backfill_hierarchy(self, batch_size: int = 1000, shapes: Iterable[str] | None = None) -> dict:
        """See the interface. Scans each shape, writes in batches with the shape's
        condition re-checked (UPSERT, so a re-run adds nothing), then scans again
        and raises if anything is left."""
        c = CollectionNames
        bind = {
            "@apps": c.APPS.value, "@groups": c.RECORD_GROUPS.value, "@records": c.RECORDS.value,
            "@belongs_to": c.BELONGS_TO.value, "@nr": c.NODE_RELATIONS.value, "@ip": c.INHERIT_PERMISSIONS.value,
            "@perm": c.PERMISSION.value, "hierarchy": sorted(HIERARCHY_RELATION_TYPES),
        }

        def _bind(query: str) -> dict:
            # Arango rejects a bind parameter the query does not use.
            return {k: v for k, v in bind.items() if "@" + k in query}

        scans = {
            name: self._BACKFILL_PAIRS[name]
                .replace("{has_parent_r}", self._BACKFILL_HAS_PARENT.format(v="r._id"))
                .replace("{has_parent_g}", self._BACKFILL_HAS_PARENT.format(v="g._id"))
            for name in self._backfill_shapes(self._BACKFILL_PAIRS, shapes)
        }
        added: dict[str, int] = {}
        for name, scan in scans.items():
            # One edge per child: several paths to the same pair are one pair.
            pairs = list({tuple(p): p for p in await self.http_client.execute_aql(scan, _bind(scan)) or []}.values())
            if name == "nested_inheritance":
                # Child to parent, the direction inheritance runs.
                write = """
                FOR pr IN @pairs
                    FILTER LENGTH(FOR i IN @@ip FILTER i._from == pr[1] AND i._to == pr[0] LIMIT 1 RETURN 1) == 0
                    INSERT {_from: pr[1], _to: pr[0], createdAtTimestamp: DATE_NOW(), updatedAtTimestamp: DATE_NOW()}
                        INTO @@ip
                    RETURN 1"""
            else:
                recheck = self._BACKFILL_RECHECK[name].replace(
                    "{has_parent}", self._BACKFILL_HAS_PARENT.format(v="pr[1]"))
                write = f"""
                FOR pr IN @pairs
                    {recheck}
                    INSERT {{_from: pr[0], _to: pr[1], relationshipType: "PARENT_CHILD",
                             createdAtTimestamp: DATE_NOW(), updatedAtTimestamp: DATE_NOW()}} INTO @@nr
                    RETURN 1"""
            n = 0
            for i in range(0, len(pairs), batch_size):
                wbind = {**_bind(write), "pairs": pairs[i:i + batch_size]}
                n += len(await self.http_client.execute_aql(write, wbind) or [])
            added[name] = n
        for name, scan in scans.items():
            left = await self.http_client.execute_aql(scan, _bind(scan))
            if left:
                raise RuntimeError(f"Hierarchy backfill left {len(left)} {name} edge(s) unwritten")
        return {"added": added}

    async def remove_inherited_record_grants(
        self, connector_names: list[str], record_types: list[str], batch_size: int = 1000,
    ) -> dict:
        """See the interface. Pages through the records by key, removes each
        page's grants with the rule re-checked, then checks that none is left."""
        c = CollectionNames
        # One of the record's grantees holds a grant on a live group the record
        # belongs to and inherits from: that grantee keeps the record through it.
        repeats = """LENGTH(
                FOR i IN @@ip
                    FILTER i._from == r._id AND IS_SAME_COLLECTION("recordGroups", i._to)
                    LET g = DOCUMENT(i._to)
                    FILTER g != null AND g.isDeleted != true
                    FILTER LENGTH(FOR b IN @@belongs_to FILTER b._from == r._id AND b._to == g._id
                                  LIMIT 1 RETURN 1) > 0
                    FILTER LENGTH(FOR p IN @@perm FILTER p._to == r._id
                                      FOR q IN @@perm FILTER q._to == g._id AND q._from == p._from
                                      LIMIT 1 RETURN 1) > 0
                    LIMIT 1 RETURN 1) > 0"""
        granted = "LENGTH(FOR gp IN @@perm FILTER gp._to == r._id LIMIT 1 RETURN 1) > 0"
        bind = {
            "@records": c.RECORDS.value, "@ip": c.INHERIT_PERMISSIONS.value, "@perm": c.PERMISSION.value,
            "@belongs_to": c.BELONGS_TO.value,
        }
        selection = {"connectors": list(connector_names), "types": list(record_types)}
        page_query = f"""
            FOR r IN @@records
                FILTER r._key > @after
                FILTER r.connectorName IN @connectors AND r.recordType IN @types
                SORT r._key
                LIMIT @batch
                RETURN [r._key, {granted} ? {repeats} : false]"""
        # Decided per record before any grant goes: once the owner's grant is gone
        # the recipients' would no longer match.
        remove_query = f"""
            LET ids = (FOR r IN @@records FILTER r._key IN @keys FILTER {repeats} RETURN r._id)
            FOR e IN @@perm
                FILTER e._to IN ids
                REMOVE e IN @@perm
                RETURN e._to"""
        removed, records, after = 0, set(), ""
        while True:
            page = await self.http_client.execute_aql(
                page_query, {**bind, **selection, "after": after, "batch": int(batch_size)},
            ) or []
            keys = [key for key, hit in page if hit]
            if keys:
                gone = await self.http_client.execute_aql(remove_query, {**bind, "keys": keys}) or []
                removed += len(gone)
                records.update(gone)
            if len(page) < batch_size:
                break
            after = page[-1][0]
        left = await self.http_client.execute_aql(
            f"""RETURN LENGTH(
                FOR r IN @@records
                    FILTER r.connectorName IN @connectors AND r.recordType IN @types
                    FILTER {granted}
                    FILTER {repeats}
                    LIMIT 1 RETURN 1)""",
            {**bind, **selection},
        )
        if left and left[0]:
            raise RuntimeError("Grant(s) left on inheriting records after the removal")
        return {"removed": removed, "records": len(records)}

    async def merge_duplicate_user_groups(self, connector_names: list[str]) -> dict:
        """See the interface. Plain queries, each idempotent: a run that stops part
        way is finished by the next one."""
        groups = CollectionNames.GROUPS.value
        duplicated = f"""
            FOR g IN {groups}
                FILTER g.connectorName IN @connectors AND g.connectorId != null AND g.externalGroupId != null
                COLLECT connector = g.connectorId, external = g.externalGroupId
                    INTO copies = {{key: g._key, at: g.createdAtTimestamp == null ? 0 : g.createdAtTimestamp}}
                FILTER LENGTH(copies) > 1
                LET ordered = (FOR c IN copies SORT c.at, c.key RETURN c.key)"""
        bind = {"connectors": list(connector_names)}
        pairs = await self.http_client.execute_aql(
            f"{duplicated} RETURN {{keeper: FIRST(ordered), dups: SLICE(ordered, 1)}}", bind
        ) or []
        if not pairs:
            return {"groups": 0, "removed": 0, "moved": 0}
        moved = 0
        for collection in (CollectionNames.PERMISSION.value, CollectionNames.BELONGS_TO.value):
            for near, far in (("_from", "_to"), ("_to", "_from")):
                # One edge per (keeper, other end), and none the keeper already has.
                out = await self.http_client.execute_aql(
                    f"""
                    FOR p IN @pairs
                        LET keeper = CONCAT(@groups, "/", p.keeper)
                        LET dups = (FOR d IN p.dups RETURN CONCAT(@groups, "/", d))
                        FOR d IN dups
                            FOR e IN @@c
                                FILTER e.{near} == d AND e.{far} NOT IN dups AND e.{far} != keeper
                                COLLECT k = keeper, other = e.{far} INTO found = e
                                FILTER LENGTH(
                                    FOR x IN @@c FILTER x.{near} == k AND x.{far} == other LIMIT 1 RETURN 1
                                ) == 0
                                INSERT MERGE(UNSET(found[0], "_key", "_id", "_rev"), {{{near}: k}}) INTO @@c
                                RETURN 1
                    """,
                    {"pairs": pairs, "groups": groups, "@c": collection},
                )
                moved += len(out or [])
                await self.http_client.execute_aql(
                    f"""
                    FOR p IN @pairs
                        FOR d IN p.dups
                            FOR e IN @@c
                                FILTER e.{near} == CONCAT(@groups, "/", d)
                                REMOVE e IN @@c
                    """,
                    {"pairs": pairs, "groups": groups, "@c": collection},
                )
        removed = await self.http_client.execute_aql(
            f"""
            FOR p IN @pairs
                FOR d IN p.dups
                    REMOVE {{_key: d}} IN {groups} OPTIONS {{ignoreErrors: true}}
                    RETURN 1
            """,
            {"pairs": pairs},
        )
        left = await self.http_client.execute_aql(f"RETURN LENGTH({duplicated} RETURN 1)", bind)
        if left and left[0]:
            raise RuntimeError(f"{left[0]} duplicated group(s) left after the merge")
        return {"groups": len(pairs), "removed": len(removed or []), "moved": moved}

    async def split_link_edges(self, batch_size: int = 1000) -> dict:
        """See the interface. One scan for the links still in nodeRelations, then
        batches that move each into recordLinks under the upsert's key (two
        foreign keys between the same tables stay two edges) and remove it, then
        a check that none is left, so a partial run leaves the flag unset. Plain
        queries: a stream transaction has no intermediate commits."""
        node_relations, links = CollectionNames.NODE_RELATIONS.value, CollectionNames.RECORD_LINKS.value
        if not await self.http_client.has_collection(links):
            raise RuntimeError(f"Collection '{links}' does not exist yet")
        hierarchy = sorted(HIERARCHY_RELATION_TYPES)
        # Outlook once wrote the type under `relationType`; it is read as the type.
        link_filter = """
            LET t = NOT_NULL(e.relationshipType, e.relationType)
            FILTER t != null AND t NOT IN @hierarchy"""
        keys = await self.http_client.execute_aql(
            f"FOR e IN @@nr {link_filter} RETURN e._key",
            {"@nr": node_relations, "hierarchy": hierarchy},
        ) or []
        moved = 0
        for i in range(0, len(keys), batch_size):
            rows = await self.http_client.execute_aql(
                f"""
                FOR e IN @@nr
                    FILTER e._key IN @keys
                    {link_filter}
                    LET cn = NOT_NULL(e.constraintName, "")
                    UPSERT {{_from: e._from, _to: e._to, relationshipType: t, constraintName: cn}}
                        INSERT MERGE(UNSET(e, "_id", "_key", "_rev", "relationType"),
                                     {{relationshipType: t, constraintName: cn}})
                        UPDATE {{}}
                        IN @@links
                    REMOVE e IN @@nr
                    RETURN 1
                """,
                {"@nr": node_relations, "@links": links, "hierarchy": hierarchy, "keys": keys[i:i + batch_size]},
            )
            moved += len(rows or [])
        left = await self.http_client.execute_aql(
            f"RETURN LENGTH(FOR e IN @@nr {link_filter} LIMIT 1 RETURN 1)",
            {"@nr": node_relations, "hierarchy": hierarchy},
        )
        if left and left[0]:
            raise RuntimeError("Links are still stored in nodeRelations after the split")
        return {"migrated": moved}

    async def backfill_app_org_ids(self) -> dict:
        """See the interface."""
        rows = await self.execute_query(
            """
            LET candidates = (
                FOR app IN @@apps
                    FILTER app.orgId == null
                    LET orgs = UNIQUE(
                        FOR edge IN @@org_app_edges
                            FILTER edge._to == app._id
                            RETURN PARSE_IDENTIFIER(edge._from).key
                    )
                    FILTER LENGTH(orgs) > 0
                    RETURN {key: app._key, orgs}
            )
            LET updated = (
                FOR c IN candidates
                    FILTER LENGTH(c.orgs) == 1
                    UPDATE c.key WITH {orgId: c.orgs[0]} IN @@apps
                    RETURN 1
            )
            RETURN {backfilled: LENGTH(updated), ambiguous: LENGTH(candidates) - LENGTH(updated)}
            """,
            bind_vars={
                "@apps": CollectionNames.APPS.value,
                "@org_app_edges": CollectionNames.ORG_APP_RELATION.value,
            },
        )
        row = (rows or [{}])[0] or {}
        return {"backfilled": row.get("backfilled") or 0, "ambiguous": row.get("ambiguous") or 0}

    async def get_user_connector_instances(
        self,
        collection: str,
        user_id: str,
        org_id: str,
        team_scope: str,
        personal_scope: str,
        transaction: str | None = None,
    ) -> list[dict]:
        """Get all connector instances accessible to a user (personal + team)."""
        try:
            query = """
            FOR doc IN @@collection
                FILTER doc._id != null
                FILTER LENGTH(
                    FOR e IN @@org_edge_collection
                        FILTER e._to == doc._id AND e._from == @org_handle
                        LIMIT 1
                        RETURN 1
                ) > 0
                FILTER (
                    doc.scope == @team_scope OR
                    (doc.scope == @personal_scope AND doc.createdBy == @user_id)
                )
                RETURN doc
            """
            bind_vars = {
                "@collection": collection,
                "@org_edge_collection": CollectionNames.ORG_APP_RELATION.value,
                "org_handle": f"{CollectionNames.ORGS.value}/{org_id}",
                "team_scope": team_scope,
                "personal_scope": personal_scope,
                "user_id": user_id,
            }
            results = await self.execute_query(query, bind_vars=bind_vars, transaction=transaction)
            return results or []

        except Exception as e:
            self.logger.error(f"Failed to get user connector instances: {e}")
            return []

    async def _get_user_accessible_team_app_keys(
        self,
        user_id: str,
        transaction: str | None = None,
    ) -> list[str]:
        """Return the ``_key`` list of team-scoped apps this user may access.

        Covers two access paths:

        1. **Direct userAppRelation edge** — ``(users/{key}) -[userAppRelation]→ (apps/{key})``
           where ``app.scope == 'team'``.  Handles connectors explicitly shared
           with a specific user.

        2. **Team-based edge** — ``(users/{key}) -[permission {type:'USER'}]→
           (teams/{key}) -[userAppRelation]→ (apps/{key})``.
           Handles the standard org-wide pattern:
           * ``ensure_all_team_with_users`` creates the user→team ``permission``
             edge (``type='USER'``).
           * ``ensure_team_app_edge`` creates the ``teams/all_{org_id} →
             userAppRelation → apps/{connector_id}`` edge when a team-scope
             connector is configured.

        Args:
            user_id: External userId value (as stored in ``user.userId``), NOT
                     the ArangoDB ``_key``.  The query resolves the ``_key``
                     internally.
            transaction: Optional ArangoDB transaction ID.

        Returns:
            List of app ``_key`` strings the user can access (empty list when
            the user has no accessible team connectors).  Any DB error is
            propagated to the caller so it is never silently swallowed.
        """
        query = f"""
        LET user_doc = FIRST(
            FOR u IN {CollectionNames.USERS.value}
                FILTER u.userId == @user_id
                LIMIT 1
                RETURN u
        )
        FILTER user_doc != null
        LET user_from = CONCAT("{CollectionNames.USERS.value}/", user_doc._key)
        LET direct_keys = (
            FOR app IN OUTBOUND user_from {CollectionNames.USER_APP_RELATION.value}
                FILTER app.scope == @team_scope
                RETURN app._key
        )
        LET team_keys = (
            FOR perm IN {CollectionNames.PERMISSION.value}
                FILTER perm._from == user_from
                FILTER perm.type == "USER"
                FILTER STARTS_WITH(perm._to, "{CollectionNames.TEAMS.value}/")
                FOR app IN OUTBOUND perm._to {CollectionNames.USER_APP_RELATION.value}
                    FILTER app.scope == @team_scope
                    RETURN app._key
        )
        FOR key IN UNION_DISTINCT(direct_keys, team_keys)
            RETURN key
        """
        results = await self.execute_query(
            query,
            bind_vars={"user_id": user_id, "team_scope": "team"},
            transaction=transaction,
        )
        return results or []

    async def get_filtered_connector_instances(
        self,
        collection: str,
        edge_collection: str,
        org_id: str,
        user_id: str,
        scope: str | None = None,
        search: str | None = None,
        skip: int = 0,
        limit: int = 20,
        *,
        exclude_kb: bool = True,
        kb_connector_type: str | None = None,
        is_admin: bool = False,
        is_authenticated: bool | None = None,
        is_active: bool | None = None,
        connector_type_filter: str | None = None,
        is_configured: bool | None = None,
        is_agent_active: bool | None = None,
        allowed_connector_types: list[str] | None = None,
        transaction: str | None = None,
    ) -> tuple[list[dict], int]:
        """Get filtered connector instances with pagination."""
        # No org, no listing: every query below is scoped by it.
        if not org_id:
            return [], 0
        try:
            # For non-admin team scope we pre-compute which team apps the user
            # can actually see.  This is done once here so the same list can be
            # reused for both the main query and the scope-count sub-query.
            accessible_team_keys: list[str] | None = None

            # The org edge is the tenant boundary: connector apps created before
            # August 2026 carry no orgId property.
            query = """
            FOR doc IN @@collection
                FILTER doc._id != null
                FILTER LENGTH(
                    FOR e IN @@org_edge_collection
                        FILTER e._to == doc._id AND e._from == @org_handle
                        LIMIT 1
                        RETURN 1
                ) > 0
                FILTER doc.scope == @team_scope OR doc.createdBy == @user_id
            """
            # Only the creator sees a personal connector, admins included: the
            # read gate refuses the rest, and count and page must agree.
            bind_vars = {
                "@collection": collection,
                "@org_edge_collection": edge_collection,
                "org_handle": f"{CollectionNames.ORGS.value}/{org_id}",
                "team_scope": "team",
                "user_id": user_id,
            }

            # The caller's org only; an App the orgId backfill could not stamp is
            # still found through its org relation.
            if org_id:
                query += (
                    " FILTER doc.orgId == @org_id OR (doc.orgId == null AND LENGTH("
                    "FOR e IN @@org_app FILTER e._from == CONCAT('organizations/', @org_id)"
                    " AND e._to == doc._id LIMIT 1 RETURN 1) > 0)\n"
                )
                bind_vars["org_id"] = org_id
                bind_vars["@org_app"] = CollectionNames.ORG_APP_RELATION.value

            # Exclude KB if requested
            if exclude_kb and kb_connector_type:
                query += " FILTER doc.type != @kb_connector_type\n"
                bind_vars["kb_connector_type"] = kb_connector_type

            # Scope filter
            # personal → only the caller's own personal connectors
            # team (admin)     → all team-scoped connectors in the org
            # team (non-admin) → only team connectors reachable via the user's
            #                    userAppRelation / permission edges
            if scope == "personal":
                query += " FILTER doc.scope == @personal_scope\n"
                query += " FILTER doc.createdBy == @user_id\n"
                bind_vars["personal_scope"] = "personal"
                bind_vars["user_id"] = user_id
            elif scope == "team":
                query += " FILTER doc.scope == @team_scope\n"
                bind_vars["team_scope"] = "team"
                if not is_admin:
                    accessible_team_keys = await self._get_user_accessible_team_app_keys(
                        user_id, transaction
                    )
                    if not accessible_team_keys:
                        self.logger.info(
                            "No accessible team app keys found for user %s — "
                            "edge data may be inconsistent (ensure_team_app_edge / "
                            "ensure_all_team_with_users not yet run for this org).",
                            user_id,
                        )
                    query += " FILTER doc._key IN @accessible_team_keys\n"
                    bind_vars["accessible_team_keys"] = accessible_team_keys

            # Search filter
            if search:
                query += " FILTER (LOWER(doc.name) LIKE @search) OR (LOWER(doc.type) LIKE @search) OR (LOWER(doc.appGroup) LIKE @search)\n"
                bind_vars["search"] = f"%{search.lower()}%"

            # is_authenticated filter
            if is_authenticated is not None:
                query += " FILTER doc.isAuthenticated == @is_authenticated\n"
                bind_vars["is_authenticated"] = is_authenticated

            # is_active filter
            if is_active is not None:
                query += " FILTER doc.isActive == @is_active\n"
                bind_vars["is_active"] = is_active

            # connector type filter
            if connector_type_filter:
                query += " FILTER doc.type == @connector_type_filter\n"
                bind_vars["connector_type_filter"] = connector_type_filter

            if is_configured is not None:
                query += " FILTER (doc.isConfigured == true) == @is_configured\n"
                bind_vars["is_configured"] = is_configured

            if is_agent_active is not None:
                query += " FILTER (doc.isAgentActive == true) == @is_agent_active\n"
                bind_vars["is_agent_active"] = is_agent_active

            if allowed_connector_types is not None:
                query += " FILTER doc.type IN @allowed_connector_types\n"
                bind_vars["allowed_connector_types"] = allowed_connector_types

            # Count query
            count_query = query + " COLLECT WITH COUNT INTO total RETURN total"
            count_result = await self.execute_query(count_query, bind_vars=bind_vars, transaction=transaction)
            total_count = count_result[0] if count_result else 0

            # Main query with pagination
            query += " SORT doc.createdAtTimestamp DESC, doc._key\n LIMIT @skip, @limit\n RETURN doc"
            bind_vars["skip"] = skip
            bind_vars["limit"] = limit

            documents = await self.execute_query(query, bind_vars=bind_vars, transaction=transaction) or []

            return documents, total_count

        except Exception as e:
            self.logger.error(f"Failed to get filtered connector instances: {e}")
            return [], 0

    async def reindex_record_group_records(
        self,
        record_group_id: str,
        depth: int,
        user_id: str,
        org_id: str,
    ) -> dict:
        """
        Validate record group and user permissions for reindexing.
        Does NOT publish events; caller (router/service) should publish.

        Returns:
            Dict with success, connectorId, connectorName, depth, recordGroupId, or error code/reason
        """
        try:
            if depth == -1:
                depth = MAX_REINDEX_DEPTH
            elif depth < 0:
                depth = 0
            record_group = await self.get_document(record_group_id, CollectionNames.RECORD_GROUPS.value)
            if not record_group:
                return {
                    "success": False,
                    "code": 404,
                    "reason": f"Record group not found: {record_group_id}",
                }
            rg = record_group if isinstance(record_group, dict) else {}
            connector_id = rg.get("connectorId") or rg.get("id") or ""
            connector_name = rg.get("connectorName") or ""
            if not connector_id or not connector_name:
                return {
                    "success": False,
                    "code": 400,
                    "reason": "Record group does not have a connector id or name",
                }

            user = await self.get_user_by_user_id(user_id)
            if not user:
                return {
                    "success": False,
                    "code": 404,
                    "reason": f"User not found: {user_id}",
                }
            user_key = user.get("_key") or user.get("id")
            if not user_key:
                return {"success": False, "code": 404, "reason": "User key not found"}
            try:
                allowed = record_group_id in (await self.check_access(
                    user_key, org_id, node_ids=[record_group_id],
                )).node_ids
            except Exception:
                self.logger.exception("❌ Access check failed for record group %s", record_group_id)
                return {"success": False, "code": 500, "reason": action_failed("check access to this record group")}
            if not allowed:
                return {
                    "success": False,
                    "code": 403,
                    "reason": "You do not have access to this record group",
                }

            # After the access check: the 409 names the connector.
            connector_doc = await self.get_document(connector_id, CollectionNames.APPS.value)
            if connector_doc and not connector_doc.get("isActive", False):
                display_name = connector_doc.get("name", "connector")
                return {
                    "success": False,
                    "code": 409,
                    "reason": f"The connector '{display_name}' is currently disabled. Enable it from Connector Settings and try again.",
                }
            return {
                "success": True,
                "connectorId": connector_id,
                "connectorName": connector_name,
                "depth": depth,
                "recordGroupId": record_group_id,
                "userKey": user_key
            }
        except Exception as e:
            self.logger.error("❌ Failed to validate record group reindex: %s", str(e))
            return {"success": False, "code": 500, "reason": str(e)}

    async def update_indexing_status_for_record_ids(self, record_ids: list[str], status: str) -> None:
        """
        Update indexingStatus to the specified status for each id (deduplicated).
        Skips missing ids and isInternal records.
        
        Args:
            record_ids: List of record IDs to update
            status: Target status (e.g., ProgressStatus.NOT_STARTED.value, ProgressStatus.QUEUED.value)
        """
        unique_ids = [rid for rid in dict.fromkeys(record_ids) if isinstance(rid, str) and rid]
        if not unique_ids:
            return
        coll = CollectionNames.RECORDS.value
        try:
            query = """
            FOR doc IN @@collection
                FILTER doc._key IN @keys
                RETURN doc
            """
            bind_vars = {"@collection": coll, "keys": unique_ids}
            raw_docs = await self.execute_query(query, bind_vars=bind_vars)
            if not raw_docs:
                return

            to_upsert: list[dict] = []
            for arango_doc in raw_docs:
                record = self._translate_node_from_arango(arango_doc)
                rid = record.get("id") or record.get("_key")
                if not rid:
                    continue
                if record.get("isInternal"):
                    continue
                if record.get("isPlaceholder"):
                    continue
                to_upsert.append({"_key": rid, "indexingStatus": status})

            if to_upsert:
                await self.batch_upsert_nodes(to_upsert, coll)
                self.logger.debug("✅ Updated %s record(s) indexing status to %s", len(to_upsert), status)
        except Exception as e:
            self.logger.error("❌ Failed to update records to %s: %s", status, str(e))

    async def reset_indexing_status_for_connector(
        self,
        connector_id: str,
        status: str,
        exclude_statuses: list[str] | None = None,
        transaction: str | None = None,
    ) -> None:
        if not connector_id:
            return
        coll = CollectionNames.RECORDS.value
        excluded = [s for s in (exclude_statuses or []) if isinstance(s, str) and s]
        try:
            exclude_clause = (
                "FILTER doc.indexingStatus NOT IN @exclude_statuses"
                if excluded
                else ""
            )
            query = f"""
            FOR doc IN @@collection
                FILTER doc.connectorId == @connector_id
                {exclude_clause}
                UPDATE doc WITH {{ indexingStatus: @status }} IN @@collection
            """
            bind_vars: dict = {
                "@collection": coll,
                "connector_id": connector_id,
                "status": status,
            }
            if excluded:
                bind_vars["exclude_statuses"] = excluded
            await self.execute_query(query, bind_vars=bind_vars, transaction=transaction)
        except Exception as e:
            # Must not be swallowed: the rebuild drops the vector collection
            # straight after this, and a connector whose records kept their old
            # statuses is never re-indexed, so search stays silently empty.
            self.logger.error(
                "❌ Failed to reset indexing status for connector %s: %s",
                connector_id,
                str(e),
            )
            raise

    async def compare_and_set_indexing_status(
        self,
        record_ids: list[str],
        expected: str,
        new_status: str,
        transaction: str | None = None,
    ) -> list[str]:
        """
        Set indexingStatus to new_status on each id, but only while that id still
        holds expected. One round-trip. Returns the ids actually updated; ids that
        held some other status were left alone, which is a normal outcome.
        """
        unique_ids = [rid for rid in dict.fromkeys(record_ids) if isinstance(rid, str) and rid]
        if not unique_ids:
            return []
        coll = CollectionNames.RECORDS.value
        try:
            bind_vars = {
                "@collection": coll,
                "keys": unique_ids,
                "expected": expected,
                "new_status": new_status,
            }
            update_fields = "{ indexingStatus: @new_status }"
            if new_status == ProgressStatus.QUEUED.value:
                # AQL rejects a declared-but-unused bind var, so only bind it here.
                update_fields = "{ indexingStatus: @new_status, queuedAtTimestamp: @now }"
                bind_vars["now"] = get_epoch_timestamp_in_ms()
            # FILTER + UPDATE in one statement; a read-then-write would let the
            # indexing service advance a record in between and get clobbered.
            query = f"""
            FOR doc IN @@collection
                FILTER doc._key IN @keys AND doc.indexingStatus == @expected
                UPDATE doc WITH {update_fields} IN @@collection
                RETURN NEW._key
            """
            updated = await self.http_client.execute_aql(query, bind_vars, transaction)
            updated_keys = [k for k in (updated or []) if isinstance(k, str)]
            self.logger.debug(
                "✅ %s/%s record(s) swapped %s -> %s",
                len(updated_keys), len(unique_ids), expected, new_status,
            )
            return updated_keys
        except Exception as e:
            self.logger.error(
                "❌ Failed compare-and-set (%s -> %s): %s",
                expected, new_status, str(e),
            )
            return []

    async def get_existing_record_keys(
        self,
        record_ids: list[str],
        transaction: str | None = None,
    ) -> set[str]:
        """Return the subset of record_ids that exist, in one round-trip."""
        unique_ids = [rid for rid in dict.fromkeys(record_ids) if isinstance(rid, str) and rid]
        if not unique_ids:
            return set()
        try:
            query = """
            FOR doc IN @@collection
                FILTER doc._key IN @keys
                RETURN doc._key
            """
            bind_vars = {"@collection": CollectionNames.RECORDS.value, "keys": unique_ids}
            found = await self.http_client.execute_aql(query, bind_vars, transaction)
            return {k for k in (found or []) if isinstance(k, str)}
        except Exception as e:
            self.logger.error("❌ Failed to check record existence: %s", str(e))
            return set()

    async def reindex_single_record(
        self,
        record_id: str,
        user_id: str,
        org_id: str,
        request: Optional[Request] = None,
        depth: int = 0,
        status_filters: list[str] | None = None,
    ) -> dict:
        """
        Reindex a single record with permission checks and event publishing.
        Depth comes from caller: 0 = only this record (record-details, collections/KB);
        >0 = include children (e.g. all-records tree uses 100).
        - KB (UPLOAD): depth > 0 uses sync-events; depth == 0 uses record-events.
        - CONNECTOR: uses sync-events and honors depth.

        Args:
            record_id: Record ID to reindex
            user_id: External user ID
            org_id: Organization ID
            request: Optional request (unused in provider; for signature compatibility)
            depth: Depth for children (0 = only this record; -1 or >MAX = normalized to MAX_REINDEX_DEPTH)

        Returns:
            Dict: success, recordId, recordName, connector, eventPublished, userRole; or error code/reason
        """
        try:
            # Normalize depth -1 -> unlimited (MAX_REINDEX_DEPTH), any other negative -> 0, >MAX -> MAX.
            if depth == -1:
                depth = MAX_REINDEX_DEPTH
            elif depth < 0:
                depth = 0
            elif depth > MAX_REINDEX_DEPTH:
                depth = MAX_REINDEX_DEPTH

            record = await self.get_document(record_id, CollectionNames.RECORDS.value)
            if not record:
                return {"success": False, "code": 404, "reason": f"Record not found: {record_id}"}
            rec = record if isinstance(record, dict) else {}
            if rec.get("isDeleted"):
                return {"success": False, "code": 400, "reason": "Cannot reindex deleted record"}
            connector_name = rec.get("connectorName", "")
            connector_id = rec.get("connectorId", "")
            origin = rec.get("origin", "")
            user = await self.get_user_by_user_id(user_id)
            if not user:
                return {"success": False, "code": 404, "reason": f"User not found: {user_id}"}
            user_key = user.get("_key") or user.get("id")
            if not user_key:
                return {"success": False, "code": 404, "reason": "User key not found"}
            user_role = None
            if origin == OriginTypes.UPLOAD.value:
                kb_context = await self._get_kb_context_for_record(record_id)
                if not kb_context:
                    return {
                        "success": False,
                        "code": 404,
                        "reason": f"Knowledge base context not found for record {record_id}",
                    }
                user_role = await self.get_user_kb_permission(kb_context.get("kb_id") or kb_context.get("id"), user_key)
                if not user_role:
                    return {
                        "success": False,
                        "code": 403,
                        "reason": "Insufficient KB permissions. Required: OWNER, WRITER, READER",
                    }
            elif origin == OriginTypes.CONNECTOR.value:
                # Anyone who may access the record may reindex it: connector
                # items carry no role.
                if record_id not in (await self.check_access(
                    user_key, org_id, node_ids=[record_id],
                )).node_ids:
                    return {
                        "success": False,
                        "code": 403,
                        "reason": "You do not have access to this record",
                    }
                if connector_id:
                    connector_doc = await self.get_document(connector_id, CollectionNames.APPS.value)
                    if connector_doc and not connector_doc.get("isActive", False):
                        display_name = connector_doc.get("name", "connector")
                        return {
                            "success": False,
                            "code": 409,
                            "reason": f"The connector '{display_name}' is currently disabled. Enable it from Connector Settings and try again.",
                        }
            else:
                return {"success": False, "code": 400, "reason": f"Unsupported record origin: {origin}"}


            # Create event data for router to publish
            try:
                if origin == OriginTypes.UPLOAD.value and depth > 0:
                    # KB folder reindex with children: use sync-events (same as connectors)
                    # Consumer will find children via get_records_by_parent_record(depth)
                    connector_for_event = connector_name.replace(" ", "").lower() if connector_name else "kb"
                    event_type = f"{connector_for_event}.reindex"

                    payload = {
                        "orgId": org_id,
                        "recordId": record_id,
                        "depth": depth,
                        "connectorId": connector_id,
                        "connector": connector_for_event,
                        "userKey": user_key,
                    }
                    if status_filters:
                        payload["statusFilters"] = status_filters

                    event_data = {
                        "eventType": event_type,
                        "topic": "sync-events",
                        "payload": payload
                    }
                elif origin == OriginTypes.UPLOAD.value:
                    # Single KB file reindex: use record-events
                    file_record = None
                    if rec.get("recordType") == "FILE":
                        file_record = await self.get_document(record_id, CollectionNames.FILES.value)

                    payload = await self._create_reindex_event_payload(rec, file_record, user_id, request, record_id=record_id)
                    event_data = {
                        "eventType": "newRecord",
                        "topic": "record-events",
                        "payload": payload
                    }
                    # Clear any terminal status so the consumer's COMPLETED gate does not
                    # skip the event. The router promotes this to QUEUED once it publishes.
                    await self.update_indexing_status_for_record_ids(
                        [record_id], ProgressStatus.NOT_STARTED.value
                    )
                else:
                    # For connector records, use sync-events with connector reindex event
                    connector_for_event = connector_name.replace(" ", "").lower() if connector_name else "unknown"
                    event_type = f"{connector_for_event}.reindex"

                    payload = {
                        "orgId": org_id,
                        "recordId": record_id,
                        "depth": depth,
                        "connectorId": connector_id,
                        "connector": connector_for_event,  # Add connector field for consumer fallback
                        "userKey": user_key,
                    }
                    if status_filters:
                        payload["statusFilters"] = status_filters

                    event_data = {
                        "eventType": event_type,
                        "topic": "sync-events",
                        "payload": payload
                    }

                return {
                    "success": True,
                    "recordId": record_id,
                    "recordName": rec.get("recordName"),
                    "connector": connector_name if origin == OriginTypes.CONNECTOR.value else Connectors.KNOWLEDGE_BASE.value,
                    "userRole": user_role,
                    "eventData": event_data,
                    "useBatchReindex": origin != OriginTypes.UPLOAD.value  # KB records don't use batch reindex
                }

            except Exception as event_error:
                self.logger.error(f"❌ Failed to create reindex event data: {str(event_error)}")
                # Return success but indicate event data creation failed
                return {
                    "success": True,
                    "recordId": record_id,
                    "recordName": rec.get("recordName"),
                    "connector": connector_name if origin == OriginTypes.CONNECTOR.value else Connectors.KNOWLEDGE_BASE.value,
                    "userRole": user_role,
                    "eventData": None,
                    "eventError": str(event_error)
                }
        except Exception as e:
            self.logger.error("❌ Failed to reindex record %s: %s", record_id, str(e))
            return {"success": False, "code": 500, "reason": str(e)}

    async def batch_upsert_nodes(
        self,
        nodes: list[dict],
        collection: str,
        transaction: str | None = None
    ) -> bool | None:
        """
        Batch upsert nodes - FULLY ASYNC.

        Args:
            nodes: List of node documents in generic format (with 'id' field)
            collection: Collection name
            transaction: Optional transaction ID

        Returns:
            Optional[bool]: True if successful
        """
        try:
            if not nodes:
                return True

            # Translate nodes from generic format to ArangoDB format
            arango_nodes = self._translate_nodes_to_arango(nodes)

            result = await self.http_client.batch_insert_documents(
                collection, arango_nodes, txn_id=transaction, overwrite=True
            )

            return result.get("errors", 0) == 0

        except Exception as e:
            self.logger.error(f"❌ Batch upsert failed: {str(e)}")
            raise

    async def _upsert_record_nodes_releasing_trash(
        self, nodes: list[dict], transaction: str | None = None
    ) -> None:
        """Upsert record nodes; records in the trash holding one of their external ids give it up.

        One query, as on Neo4j. It writes like ``batch_upsert_nodes`` (insert or
        merge into the stored document), and AQL modifies a collection once per
        query, so the releases go through the same INSERT.
        """
        docs = self._translate_nodes_to_arango(nodes)
        await self.execute_query(
            """
            LET releases = (
                FOR node IN @docs
                    FILTER node.externalRecordId != null
                    FOR holder IN @@records
                        FILTER holder.externalRecordId == node.externalRecordId
                            AND holder.connectorId == node.connectorId
                        FILTER holder.isDeleted == true AND holder._key NOT IN @keys
                        COLLECT key = holder._key, external_id = holder.externalRecordId
                        RETURN {
                            _key: key,
                            externalRecordId: CONCAT(@trashed_prefix, key),
                            trashedExternalRecordId: external_id
                        }
            )
            FOR doc IN APPEND(releases, @docs)
                INSERT doc INTO @@records OPTIONS { overwriteMode: "update" }
                RETURN NEW._key
            """,
            bind_vars={
                "docs": docs,
                "keys": [doc["_key"] for doc in docs],
                "trashed_prefix": TRASHED_EXTERNAL_ID_PREFIX,
                "@records": CollectionNames.RECORDS.value,
            },
            transaction=transaction,
        )

    async def delete_nodes(
        self,
        keys: list[str],
        collection: str,
        transaction: str | None = None
    ) -> bool:
        """
        Delete multiple nodes - FULLY ASYNC.

        Args:
            keys: List of document keys
            collection: Collection name
            transaction: Optional transaction ID

        Returns:
            bool: True if successful
        """
        try:
            deleted = await self.http_client.batch_delete_documents(
                collection, keys, txn_id=transaction
            )
            return deleted == len(keys)
        except Exception as e:
            self.logger.error(f"❌ Delete nodes failed: {str(e)}")
            raise

    async def update_node(
        self,
        key: str,
        collection: str,
        updates: dict,
        transaction: str | None = None
    ) -> bool:
        """
        Update a single node - FULLY ASYNC.

        Args:
            key: Document key
            collection: Collection name
            updates: Fields to update
            transaction: Optional transaction ID

        Returns:
            bool: True if successful
        """
        try:
            result = await self.http_client.update_document(
                collection, key, updates, txn_id=transaction
            )
            return result is not None
        except Exception as e:
            self.logger.error(f"❌ Update node failed: {str(e)}")
            raise

    async def update_node_if_match(
        self,
        key: str,
        collection: str,
        node: dict,
        match_field: str,
        match_value: Any,
        transaction: str | None = None,
    ) -> bool:
        """REPLACE the document only while `match_field` still equals
        `match_value`. FILTER + REPLACE is one AQL statement so a concurrent
        overwrite cannot sneak in between the check and the write."""
        try:
            arango_node = self._translate_node_to_arango(node)
            arango_node["_key"] = key
            query = """
            FOR doc IN @@collection
                FILTER doc._key == @key AND doc[@field] == @expected
                REPLACE doc WITH @node IN @@collection
                RETURN NEW._key
            """
            updated = await self.http_client.execute_aql(
                query,
                {
                    "@collection": collection,
                    "key": key,
                    "field": match_field,
                    "expected": match_value,
                    "node": arango_node,
                },
                transaction,
            )
            return bool(updated)
        except Exception as e:
            self.logger.error("❌ Conditional node update failed: %s", str(e))
            raise

    async def batch_update_nodes(
        self,
        nodes: list[dict],
        collection: str,
        transaction: str | None = None
    ) -> bool | None:
        """
        Batch update existing nodes only - FULLY ASYNC.
        
        This method ONLY updates nodes that already exist. It does NOT create new nodes.
        Uses ArangoDB UPDATE (not UPSERT) to ensure no accidental record creation.

        Args:
            nodes: List of node documents in generic format (with 'id' or '_key' field)
            collection: Collection name
            transaction: Optional transaction ID

        Returns:
            Optional[bool]: True if successful, False if any updates failed
        """
        try:
            if not nodes:
                return True

            # Translate nodes from generic format to ArangoDB format
            arango_nodes = self._translate_nodes_to_arango(nodes)

            # Build AQL query for batch UPDATE (not UPSERT)
            # This will only update existing documents and skip non-existent ones
            bind_vars = {
                "nodes": arango_nodes
            }

            aql_query = f"""
                FOR doc IN @nodes
                    UPDATE doc IN @@collection
                    OPTIONS {{ ignoreErrors: true }}
                    RETURN NEW
            """

            bind_vars["@collection"] = collection

            result = await self.http_client.execute_aql(aql_query, bind_vars, txn_id=transaction)

            # Check if all updates succeeded
            if result and isinstance(result, list):
                # Filter out None values (failed updates)
                successful_updates = [r for r in result if r is not None]
                if len(successful_updates) != len(arango_nodes):
                    self.logger.warning(
                        f"⚠️ Batch update failed: {len(successful_updates)}/{len(arango_nodes)} nodes updated. "
                        f"{len(arango_nodes) - len(successful_updates)} nodes may not exist in the database."
                    )
                    return False  # Return False if not all updates succeeded
                return True  # All updates succeeded
            
            return False

        except Exception as e:
            self.logger.error(f"❌ Batch update failed: {str(e)}")
            raise

    # ==================== Edge Operations ====================

    @staticmethod
    def _logical_edge_collections(collection: str) -> list[str]:
        """The collections a node-wide read or delete over this collection covers.
        nodeRelations holds the hierarchy and recordLinks the links; writes route
        by type, and single-pair operations stay on the hierarchy."""
        if collection == CollectionNames.NODE_RELATIONS.value:
            return [collection, CollectionNames.RECORD_LINKS.value]
        return [collection]

    @staticmethod
    def _is_link(edge: dict) -> bool:
        relationship_type = edge.get("relationshipType")
        return relationship_type is not None and relationship_type not in HIERARCHY_RELATION_TYPES

    async def batch_create_edges(
        self,
        edges: list[dict],
        collection: str,
        transaction: str | None = None
    ) -> bool:
        """
        Batch create edges - FULLY ASYNC.

        Uses UPSERT to avoid duplicates - matches on _from and _to.

        Args:
            edges: List of edge documents in generic format (from_id, from_collection, to_id, to_collection)
            collection: Edge collection name
            transaction: Optional transaction ID

        Returns:
            bool: True if successful
        """
        try:
            if not edges:
                return True

            self.logger.debug(f"🚀 Batch creating edges: {collection}")

            # Translate edges from generic format to ArangoDB format
            arango_edges = self._translate_edges_to_arango(edges)

            if collection != CollectionNames.NODE_RELATIONS.value:
                batch_query = """
                FOR edge IN @edges
                    UPSERT { _from: edge._from, _to: edge._to }
                    INSERT edge
                    REPLACE UNSET(MERGE(OLD, edge), "_id", "_rev", "pendingSweep")
                    IN @@collection
                    RETURN NEW
                """
                results = await self.http_client.execute_aql(
                    batch_query, {"edges": arango_edges, "@collection": collection}, txn_id=transaction,
                )
                self.logger.debug(f"✅ Successfully created {len(results)} edges in collection '{collection}'.")
                return True

            # A link goes to recordLinks and is keyed on its type too, so a BLOCKS
            # and a RELATED between one pair are two edges. A hierarchy write never
            # matches a link still waiting in nodeRelations for the migration,
            # which it would otherwise overwrite.
            links = [e for e in arango_edges if self._is_link(e)]
            hierarchy = [e for e in arango_edges if not self._is_link(e)]
            if hierarchy:
                await self.http_client.execute_aql(
                    """
                    FOR edge IN @edges
                        UPSERT FILTER CURRENT._from == edge._from AND CURRENT._to == edge._to
                            AND (CURRENT.relationshipType == null OR CURRENT.relationshipType IN @hierarchy)
                        INSERT edge
                        REPLACE UNSET(MERGE(OLD, edge), "_id", "_rev", "pendingSweep")
                        IN @@collection
                        RETURN 1
                    """,
                    {"edges": hierarchy, "hierarchy": sorted(HIERARCHY_RELATION_TYPES), "@collection": collection},
                    txn_id=transaction,
                )
            if links:
                await self.http_client.execute_aql(
                    """
                    FOR edge IN @edges
                        UPSERT { _from: edge._from, _to: edge._to, relationshipType: edge.relationshipType }
                        INSERT edge
                        REPLACE UNSET(MERGE(OLD, edge), "_id", "_rev", "pendingSweep")
                        IN @@links
                        RETURN 1
                    """,
                    {"edges": links, "@links": CollectionNames.RECORD_LINKS.value},
                    txn_id=transaction,
                )
            self.logger.debug(f"✅ Created {len(hierarchy)} hierarchy edge(s) and {len(links)} link(s).")
            return True

        except Exception as e:
            self.logger.error(f"❌ Batch edge creation failed: {str(e)}")
            raise

    async def create_edges_if_absent(
        self,
        edges: list[dict],
        collection: str,
        transaction: str | None = None
    ) -> None:
        """Create the edges that are not there; an existing edge keeps its document.

        Not batch_create_edges: that does ``UPDATE edge``, which would reset a live
        edge (a sync state, a role) when a repair re-runs over it. An edge only a
        running full sync's tag keeps counts as absent, as it would after a wipe.
        """
        try:
            if not edges:
                return

            arango_edges = self._translate_edges_to_arango(edges)

            query = """
            FOR edge IN @edges
                UPSERT { _from: edge._from, _to: edge._to }
                INSERT edge
                REPLACE OLD.pendingSweep == null OR OLD.pendingSweep NOT IN @running
                    ? UNSET(OLD, "_id", "_rev") : UNSET(MERGE(OLD, edge), "_id", "_rev", "pendingSweep")
                IN @@collection
            """
            await self.http_client.execute_aql(
                query,
                {"edges": arango_edges, "@collection": collection, "running": running_generations()},
                txn_id=transaction
            )

        except Exception as e:
            self.logger.error(f"❌ Create edges if absent failed: {str(e)}")
            raise

    async def batch_create_entity_relations(
        self,
        edges: list[dict],
        transaction: str | None = None
    ) -> bool:
        """
        Batch create entity relation edges - FULLY ASYNC.

        Uses UPSERT to avoid duplicates - matches on _from, _to, and edgeType.
        This is specialized for entityRelations collection where multiple edges
        can exist between the same entities with different edgeType values (e.g., ASSIGNED_TO, CREATED_BY, REPORTED_BY).

        Args:
            edges: List of edge documents with _from, _to, and edgeType
            transaction: Optional transaction ID

        Returns:
            bool: True if successful
        """
        try:
            if not edges:
                return True

            self.logger.debug("🚀 Batch creating entity relation edges")

            # Translate edges from generic format to ArangoDB format
            arango_edges = self._translate_edges_to_arango(edges)

            # For entity relations, include edgeType in the UPSERT match condition
            batch_query = """
            FOR edge IN @edges
                UPSERT { _from: edge._from, _to: edge._to, edgeType: edge.edgeType }
                INSERT edge
                REPLACE UNSET(MERGE(OLD, edge), "_id", "_rev", "pendingSweep")
                IN @@collection
                RETURN NEW
            """
            bind_vars = {
                "edges": arango_edges,
                "@collection": CollectionNames.ENTITY_RELATIONS.value
            }

            results = await self.http_client.execute_aql(
                batch_query,
                bind_vars,
                txn_id=transaction
            )

            self.logger.debug(
                f"✅ Successfully created {len(results)} entity relation edges."
            )
            return True

        except Exception as e:
            self.logger.error(f"❌ Batch entity relation creation failed: {str(e)}")
            raise

    async def batch_upsert_node_relations(
        self,
        edges: list[dict],
        transaction: Optional[str] = None
    ) -> bool:
        """
        Batch upsert record relation edges - FULLY ASYNC.

        Uses UPSERT to avoid duplicates - matches on _from, _to, relationshipType, and constraintName.
        This allows multiple edges between the same record pair with different
        relation types (e.g., FOREIGN_KEY and DEPENDS_ON) or different constraint names
        (e.g., two FKs from the same table to the same target table).

        Args:
            edges: List of edge documents with _from, _to, relationshipType, and optionally constraintName
            transaction: Optional transaction ID

        Returns:
            bool: True if successful
        """
        try:
            if not edges:
                return True

            self.logger.debug("🚀 Batch upserting record relation edges")

            arango_edges = self._translate_edges_to_arango(edges)
            batch_query = """
            FOR edge IN @edges
                UPSERT { _from: edge._from, _to: edge._to, relationshipType: edge.relationshipType, constraintName: edge.constraintName }
                INSERT edge
                REPLACE UNSET(MERGE(OLD, edge), "_id", "_rev", "pendingSweep")
                IN @@collection
                RETURN NEW
            """
            # Links go to their own collection, with the same key.
            upserted = 0
            for target, group in (
                (CollectionNames.NODE_RELATIONS.value, [e for e in arango_edges if not self._is_link(e)]),
                (CollectionNames.RECORD_LINKS.value, [e for e in arango_edges if self._is_link(e)]),
            ):
                if group:
                    results = await self.http_client.execute_aql(
                        batch_query, {"edges": group, "@collection": target}, txn_id=transaction,
                    )
                    upserted += len(results or [])

            self.logger.debug(f"✅ Successfully upserted {upserted} record relation edges.")
            return True

        except Exception as e:
            self.logger.error(f"❌ Batch record relation upsert failed: {str(e)}")
            raise

    async def get_edge(
        self,
        from_id: str,
        from_collection: str,
        to_id: str,
        to_collection: str,
        collection: str,
        transaction: str | None = None
    ) -> dict | None:
        """
        Get an edge between two nodes - FULLY ASYNC.

        Args:
            from_id: Source node ID
            from_collection: Source node collection name
            to_id: Target node ID
            to_collection: Target node collection name
            collection: Edge collection name
            transaction: Optional transaction ID

        Returns:
            Optional[Dict]: Edge data in generic format or None
        """
        # Construct ArangoDB-style _from and _to values
        from_node = f"{from_collection}/{from_id}"
        to_node = f"{to_collection}/{to_id}"

        query = f"""
        FOR edge IN {collection}
            FILTER edge._from == @from_node AND edge._to == @to_node
            LIMIT 1
            RETURN edge
        """

        try:
            results = await self.http_client.execute_aql(
                query,
                {"from_node": from_node, "to_node": to_node},
                txn_id=transaction
            )
            if results:
                # Translate from ArangoDB format to generic format
                return self._translate_edge_from_arango(results[0])
            return None
        except Exception as e:
            self.logger.error(f"❌ Get edge failed: {str(e)}")
            return None

    async def delete_edge(
        self,
        from_id: str,
        from_collection: str,
        to_id: str,
        to_collection: str,
        collection: str,
        transaction: str | None = None
    ) -> bool:
        """
        Delete an edge - FULLY ASYNC.

        Args:
            from_id: Source node ID
            from_collection: Source node collection name
            to_id: Target node ID
            to_collection: Target node collection name
            collection: Edge collection name
            transaction: Optional transaction ID

        Returns:
            bool: True if successful, False otherwise
        """
        # Every edge of the pair, as on Neo4j, and a failure raises so the caller's
        # transaction rolls back. A single-pair delete stays on the hierarchy: a
        # link between the same pair survives a re-parenting.
        from_node = f"{from_collection}/{from_id}"
        to_node = f"{to_collection}/{to_id}"
        try:
            removed = await self.http_client.execute_aql(
                """
                FOR edge IN @@collection
                    FILTER edge._from == @from_node AND edge._to == @to_node
                    REMOVE edge IN @@collection
                    RETURN 1
                """,
                {"@collection": collection, "from_node": from_node, "to_node": to_node},
                txn_id=transaction,
            )
            return bool(removed)
        except Exception as e:
            self.logger.error(f"❌ Delete edge failed: {str(e)}")
            raise

    async def batch_delete_edges(
        self,
        edges: list[dict],
        collection: str,
        transaction: str | None = None
    ) -> int:
        """
        Batch delete edges between node pairs - FULLY ASYNC.

        Args:
            edges: List of edges in generic format
            collection: Edge collection name
            transaction: Optional transaction ID

        Returns:
            int: Number of edges deleted
        """
        try:
            if not edges:
                return 0

            arango_edges = self._translate_edges_to_arango(edges)

            batch_query = """
            FOR edge IN @edges
                FOR rel IN @@collection
                    FILTER rel._from == edge._from AND rel._to == edge._to
                    REMOVE rel IN @@collection
                    RETURN 1
            """
            bind_vars = {"edges": arango_edges, "@collection": collection}

            results = await self.http_client.execute_aql(
                batch_query,
                bind_vars,
                txn_id=transaction,
            )
            return len(results)

        except Exception as e:
            self.logger.error(f"❌ Batch delete edges failed: {str(e)}")
            raise

    async def delete_edges_from(
        self,
        from_id: str,
        from_collection: str,
        collection: str,
        transaction: str | None = None
    ) -> int:
        """
        Delete all edges from a node - FULLY ASYNC.

        Args:
            from_id: Source node ID
            from_collection: Source node collection name
            collection: Edge collection name
            transaction: Optional transaction ID

        Returns:
            int: Number of edges deleted
        """
        # Construct ArangoDB-style _from value
        from_node = f"{from_collection}/{from_id}"

        try:
            deleted = 0
            for edges in self._logical_edge_collections(collection):
                results = await self.http_client.execute_aql(
                    f"""
                    FOR edge IN {edges}
                        FILTER edge._from == @from_node
                        REMOVE edge IN {edges}
                        RETURN OLD
                    """,
                    {"from_node": from_node},
                    txn_id=transaction,
                )
                deleted += len(results)
            return deleted
        except Exception as e:
            self.logger.error(f"❌ Delete edges from failed: {str(e)}")
            raise

