    async def get_record_by_external_id(
        self,
        connector_id: str,
        external_id: str,
        transaction: str | None = None,
        visibility: RecordVisibility = RecordVisibility.LIVE,
    ) -> Record | None:
        """Get record by external ID"""
        query = f"""
        FOR doc IN {CollectionNames.RECORDS.value}
            FILTER doc.externalRecordId == @external_id
            AND doc.connectorId == @connector_id
            AND {aql_record_visibility("doc", visibility)}
            LIMIT 1
            RETURN doc
        """

        try:
            results = await self.http_client.execute_aql(
                query,
                bind_vars={
                    "external_id": external_id,
                    "connector_id": connector_id
                },
                txn_id=transaction
            )
            if results:
                record_data = self._translate_node_from_arango(results[0])
                return Record.from_arango_base_record(record_data)
            return None
        except Exception as e:
            self.logger.error(f"❌ Get record by external ID failed: {str(e)}")
            raise GraphQueryError(
                f"Could not look up record {external_id}: {e}"
            ) from e

    async def find_slack_burst_record_by_ts(
        self,
        connector_id: str,
        channel_id: str,
        ts: str,
        transaction: Optional[str] = None,
    ) -> Optional[MessageRecord]:
        """
        Find the Slack burst MessageRecord whose startTs <= ts <= endTs.

        Joins the MESSAGES collection (which holds startTs / endTs / isReply)
        with the RECORDS collection (which holds connectorId / externalGroupId) via
        the shared document _key.

        Returns the first matching MessageRecord, or None.
        """
        query = f"""
            FOR m IN {CollectionNames.MESSAGES.value}
                FILTER m.startTs != null
                AND    m.endTs   != null
                AND    m.startTs <= @ts
                AND    m.endTs   >= @ts
                AND    m.startTs != m.endTs
                LET r = DOCUMENT({CollectionNames.RECORDS.value}, m._key)
                FILTER r != null
                AND    r.connectorId     == @connector_id
                AND    r.externalGroupId == @channel_id
                LIMIT 1
                RETURN {{message: m, record: r}}
        """
        try:
            results = await self.http_client.execute_aql(
                query,
                bind_vars={
                    "connector_id": connector_id,
                    "channel_id": channel_id,
                    "ts": ts,
                },
                txn_id=transaction,
            )
            if not results:
                return None
            row = results[0]
            return MessageRecord.from_arango_record(row["message"], row["record"])
        except Exception as exc:
            self.logger.error(f"❌ find_slack_burst_record_by_ts({ts}) failed: {exc}")
            return None

    async def get_record_path(
        self,
        record_id: str,
        transaction: str | None = None
    ) -> str | None:
        """
        Get full hierarchical path for a record by traversing graph bottom to top.

        Traverses up through NODE_RELATIONS edges (PARENT_CHILD relationship)
        to build a path like: "Folder1/Subfolder/File.txt"

        Args:
            record_id: The record key to get the path for
            transaction: Optional transaction ID

        Returns:
            Optional[str]: The full path as a string (e.g., "Folder1/Subfolder/File.txt")
                        or None if record not found

        Hardcoded depth to 100
        """
        try:
            query = """
            LET start_record = DOCUMENT(@records_collection, @record_id)
            FILTER start_record != null
            // Follow PARENT_CHILD and ATTACHMENT edges to build hierarchical paths for both pages and attachments
            LET ancestors = (
                FOR v, e, p IN 1..100 INBOUND start_record @@node_relations
                    PRUNE e != null AND (e.relationshipType NOT IN ['PARENT_CHILD', 'ATTACHMENT']
                        OR (v.externalRecordId != p.vertices[LENGTH(p.vertices)-2].externalParentId
                            AND v._key != p.vertices[LENGTH(p.vertices)-2].externalParentId))
                    FILTER p.edges[*].relationshipType ALL IN ['PARENT_CHILD', 'ATTACHMENT']
                    FILTER v.externalRecordId == p.vertices[LENGTH(p.vertices)-2].externalParentId
                        OR v._key == p.vertices[LENGTH(p.vertices)-2].externalParentId
                    RETURN v.recordName
            )
            LET path_order = REVERSE(ancestors)
            LET full_path_list = APPEND(path_order, start_record.recordName)
            LET clean_path = (
                FOR name IN full_path_list
                FILTER name != null AND name != ""
                RETURN name
            )
            RETURN CONCAT_SEPARATOR('/', clean_path)
            """

            result = await self.http_client.execute_aql(
                query,
                bind_vars={
                    "record_id": record_id,
                    "records_collection": CollectionNames.RECORDS.value,
                    "@node_relations": CollectionNames.NODE_RELATIONS.value,
                },
                txn_id=transaction
            )

            if result and len(result) > 0:
                path = result[0]
                self.logger.debug(f"✅ Found path for {record_id}: {path}")
                return path
            return None

        except Exception as e:
            self.logger.error(f"❌ Failed to get record path for {record_id}: {str(e)}")
            return None

    async def get_record_path_segments(
        self,
        record_id: str,
        transaction: str | None = None,
        *,
        raise_on_error: bool = False,
    ) -> list[str]:
        # PRUNE stops the walk at a non-canonical step but still emits that
        # vertex, so FILTER repeats the condition to drop it. The explicit
        # null check matches Cypher, where null = null is not true.
        query = f"""
        LET start_record = DOCUMENT(@records_collection, @record_id)
        FILTER start_record != null
        FOR v, e, p IN 0..100 INBOUND start_record {CollectionNames.NODE_RELATIONS.value}
            PRUNE e != null AND NOT (
                e.relationshipType IN @relation_types
                AND IS_SAME_COLLECTION(@records_collection, v)
                AND p.vertices[LENGTH(p.vertices) - 2].externalParentId != null
                AND (v.externalRecordId == p.vertices[LENGTH(p.vertices) - 2].externalParentId
                     OR v._key == p.vertices[LENGTH(p.vertices) - 2].externalParentId)
            )
            OPTIONS {{ uniqueVertices: "path" }}
            FILTER e == null OR (
                e.relationshipType IN @relation_types
                AND IS_SAME_COLLECTION(@records_collection, v)
                AND p.vertices[LENGTH(p.vertices) - 2].externalParentId != null
                AND (v.externalRecordId == p.vertices[LENGTH(p.vertices) - 2].externalParentId
                     OR v._key == p.vertices[LENGTH(p.vertices) - 2].externalParentId)
            )
            SORT LENGTH(p.vertices) DESC, p.vertices[*]._key ASC
            LIMIT @max_candidates
            RETURN {{ ids: p.vertices[*]._key, names: p.vertices[*].recordName }}
        """
        try:
            rows = await self.http_client.execute_aql(
                query,
                bind_vars={
                    "record_id": record_id,
                    "records_collection": CollectionNames.RECORDS.value,
                    "relation_types": list(CANONICAL_PARENT_RELATION_TYPES),
                    "max_candidates": PATH_MAX_CANDIDATES,
                },
                txn_id=transaction,
            )
        except Exception as e:
            self.logger.error(f"❌ Failed to get record path segments for {record_id}: {str(e)}")
            if raise_on_error:
                raise
            return []
        return select_canonical_chain_names(rows, ("names",))

    async def get_descendant_virtual_record_ids(
        self,
        record_id: str,
        transaction: str | None = None,
    ) -> list[str]:
        # Level by level with a visited set, applying the same canonical-parent
        # rule as get_record_path_segments per hop. A path traversal enumerates
        # every path, which doubles at each duplicated parent edge (2^depth).
        query = f"""
        FOR key IN @frontier
            LET parent = DOCUMENT(@records_collection, key)
            FOR v, e IN 1..1 OUTBOUND parent {CollectionNames.NODE_RELATIONS.value}
                FILTER e.relationshipType IN @relation_types
                    AND v.externalParentId != null
                    AND (v.externalParentId == parent.externalRecordId
                         OR v.externalParentId == parent._key)
                RETURN DISTINCT {{ key: v._key, vrid: v.virtualRecordId }}
        """
        visited = {record_id}
        frontier = [record_id]
        vrids: set[str] = set()
        for _ in range(100):  # same depth bound as the path walks
            if not frontier:
                break
            rows = await self.http_client.execute_aql(
                query,
                bind_vars={
                    "frontier": frontier,
                    "records_collection": CollectionNames.RECORDS.value,
                    "relation_types": list(CANONICAL_PARENT_RELATION_TYPES),
                },
                txn_id=transaction,
            )
            frontier = []
            for row in rows or []:
                if row["key"] in visited:
                    continue
                visited.add(row["key"])
                frontier.append(row["key"])
                if row["vrid"]:
                    vrids.add(row["vrid"])
        return list(vrids)

    async def get_record_group_path(
        self,
        record_group_id: str,
        transaction: str | None = None,
        *,
        raise_on_error: bool = False,
    ) -> list[str]:
        # PRUNE still emits the non-group vertex it stops at, so FILTER drops it.
        query = f"""
        LET start_rg = DOCUMENT(@rg_collection, @record_group_id)
        FILTER start_rg != null
        FOR v, e, p IN 0..50 OUTBOUND start_rg {CollectionNames.BELONGS_TO.value}
            PRUNE NOT IS_SAME_COLLECTION(@rg_collection, v)
            OPTIONS {{ uniqueVertices: "path" }}
            FILTER IS_SAME_COLLECTION(@rg_collection, v)
            SORT LENGTH(p.vertices) DESC, p.vertices[*]._key ASC
            LIMIT @max_candidates
            RETURN {{
                ids: p.vertices[*]._key,
                groupNames: p.vertices[*].groupName,
                names: p.vertices[*].name
            }}
        """
        try:
            rows = await self.http_client.execute_aql(
                query,
                bind_vars={
                    "record_group_id": record_group_id,
                    "rg_collection": CollectionNames.RECORD_GROUPS.value,
                    "max_candidates": PATH_MAX_CANDIDATES,
                },
                txn_id=transaction,
            )
        except Exception as e:
            self.logger.error(f"❌ Get record group path failed: {str(e)}")
            if raise_on_error:
                raise
            return []
        return select_canonical_chain_names(rows, ("groupNames", "names"))

    async def get_record_by_external_revision_id(
        self,
        connector_id: str,
        external_revision_id: str,
        transaction: str | None = None,
        *,
        visibility: RecordVisibility = RecordVisibility.LIVE,
    ) -> Record | None:
        """Get record by external revision ID (e.g., etag)"""
        query = f"""
        FOR doc IN {CollectionNames.RECORDS.value}
            FILTER doc.externalRevisionId == @external_revision_id
            AND doc.connectorId == @connector_id
            AND {aql_record_visibility("doc", visibility)}
            LIMIT 1
            RETURN doc
        """

        try:
            results = await self.http_client.execute_aql(
                query,
                bind_vars={
                    "external_revision_id": external_revision_id,
                    "connector_id": connector_id
                },
                txn_id=transaction
            )
            if results:
                record_data = self._translate_node_from_arango(results[0])
                return Record.from_arango_base_record(record_data)
            return None
        except Exception as e:
            self.logger.error(f"❌ Get record by external revision ID failed: {str(e)}")
            return None

    async def get_child_record_ids_by_relation_type(
        self,
        record_id: str,
        relation_type: str,
        transaction: Optional[str] = None
    ) -> list[dict[str, Any]]:
        """
        Get record _keys of all records that have an edge pointing TO this record
        with the given relation type (e.g. child tables that reference this table via FOREIGN_KEY).

        Args:
            record_id: Record _key (vertex id)
            relation_type: Edge relation type (e.g. RecordRelations.FOREIGN_KEY.value)
            transaction: Optional transaction ID

        Returns:
            List of dicts with record_id and FK metadata (childTable, sourceColumn, targetColumn).
        """
        try:
            # Both collections: a link waits in nodeRelations until it is migrated.
            query = f"""
            FOR edge IN UNION(
                    (FOR e IN {CollectionNames.RECORD_LINKS.value}
                        FILTER e._to == CONCAT("records/", @record_id) AND e.relationshipType == @relation_type
                        RETURN e),
                    (FOR e IN {CollectionNames.NODE_RELATIONS.value}
                        FILTER e._to == CONCAT("records/", @record_id) AND e.relationshipType == @relation_type
                        RETURN e))
                RETURN {{
                    record_id: PARSE_IDENTIFIER(edge._from).key,
                    childTable: edge.childTableName || "",
                    sourceColumn: edge.sourceColumn || "",
                    targetColumn: edge.targetColumn || ""
                }}
            """
            results = await self.http_client.execute_aql(
                query,
                bind_vars={"record_id": record_id, "relation_type": relation_type},
                txn_id=transaction
            )
            return list(results) if results else []
        except Exception as e:
            self.logger.warning(
                "Failed to get child record IDs by relation type for record %s: %s",
                record_id,
                str(e),
            )
            return []

