    async def create_inherit_permissions_relation_record_group(
        self,
        record_id: str,
        record_group_id: str,
        transaction: str | None = None
    ) -> None:
        """
        Create INHERIT_PERMISSIONS edge from record to record group.

        Generic implementation.
        """
        record_edge = {
            "_from": f"{CollectionNames.RECORDS.value}/{record_id}",
            "_to": f"{CollectionNames.RECORD_GROUPS.value}/{record_group_id}",
            "createdAtTimestamp": get_epoch_timestamp_in_ms(),
            "updatedAtTimestamp": get_epoch_timestamp_in_ms(),
        }

        await self.batch_create_edges(
            [record_edge],
            collection=CollectionNames.INHERIT_PERMISSIONS.value,
            transaction=transaction
        )

    async def delete_inherit_permissions_relation_record_group(
        self,
        record_id: str,
        record_group_id: str,
        transaction: str | None = None
    ) -> None:
        """
        Delete INHERIT_PERMISSIONS edge from record to record group.
        Called when a record's inherit_permissions is set to False after a placeholder was created.
        """
        await self.delete_edge(
            from_id=record_id,
            from_collection=CollectionNames.RECORDS.value,
            to_id=record_group_id,
            to_collection=CollectionNames.RECORD_GROUPS.value,
            collection=CollectionNames.INHERIT_PERMISSIONS.value,
            transaction=transaction
        )

    async def get_all_documents(
        self,
        collection: str,
        transaction: str | None = None
    ) -> list[dict]:
        """
        Get all documents from a collection.

        Args:
            collection: Collection name
            transaction: Optional transaction ID

        Returns:
            List[Dict]: List of all documents in the collection
        """
        try:
            self.logger.debug(f"🚀 Getting all documents from collection: {collection}")
            query = """
            FOR doc IN @@collection
                RETURN doc
            """
            results = await self.http_client.execute_aql(
                query,
                bind_vars={"@collection": collection},
                txn_id=transaction
            )
            return results if results else []
        except Exception as e:
            self.logger.error(f"❌ Failed to get all documents from collection: {collection}: {str(e)}")
            return []

    async def get_documents_paginated(
        self,
        collection: str,
        skip: int = 0,
        limit: int = 50,
        filters: dict | None = None,
        sort_field: str | None = None,
        transaction: str | None = None,
        *,
        raise_on_error: bool = False,
    ) -> list[dict]:
        """
        Fetch a page of documents from a collection using AQL LIMIT so that
        only the requested slice is transferred from ArangoDB, keeping memory
        usage proportional to `limit` regardless of collection size.
        """
        try:
            bind_vars: dict = {"@collection": collection, "skip": skip, "limit": limit}

            filter_clauses: list[str] = []
            if filters:
                for idx, (field, value) in enumerate(filters.items()):
                    param = f"fv{idx}"
                    filter_clauses.append(f"doc.{field} == @{param}")
                    bind_vars[param] = value

            filter_aql = (
                "FILTER " + " AND ".join(filter_clauses) if filter_clauses else ""
            )
            sort_aql = f"SORT doc.{sort_field} ASC" if sort_field else ""

            query = f"""
            FOR doc IN @@collection
                {filter_aql}
                {sort_aql}
                LIMIT @skip, @limit
                RETURN doc
            """

            results = await self.http_client.execute_aql(
                query,
                bind_vars=bind_vars,
                txn_id=transaction,
            )
            return results if results else []
        except Exception as e:
            self.logger.error(
                "Failed to get paginated documents from collection %s: %s",
                collection,
                str(e),
            )
            if raise_on_error:
                raise
            return []

    async def get_app_creator_user(
        self,
        connector_id: str,
        transaction:str | None=None
    ) -> User | None:
        try:
            app_doc = await self.get_document(
                document_key=connector_id,
                collection = CollectionNames.APPS.value,
                transaction=transaction
            )
            if not app_doc:
                return None
            created_by=app_doc.get("createdBy")
            if not created_by:
                return None
            user_doc = await self.get_user_by_user_id(
                user_id=created_by
            )
            if not user_doc:
                return None
            # NOTE: This class of type can be removed once get_user_by_user_id returns User object
            if isinstance(user_doc, dict):
                user = User.from_arango_user(user_doc)
            else:
                user = user_doc
            return user
        except Exception as e:
            self.logger.error(f"❌ Failed to fetch user for {connector_id}: {str(e)}")
            return None

    async def get_org_apps(
        self,
        org_id: str,
        *,
        active_only: bool = True,
        app_type: str | None = None,
        raise_on_error: bool = False,
    ) -> list[dict]:
        """
        Get organization apps.
        """
        try:
            active_filter = "FILTER app.isActive == true" if active_only else ""
            type_filter = "FILTER app.type == @app_type" if app_type is not None else ""
            query = f"""
            FOR app IN OUTBOUND
                '{CollectionNames.ORGS.value}/{org_id}'
                {CollectionNames.ORG_APP_RELATION.value}
            {active_filter}
            {type_filter}
            RETURN app
            """

            results = await self.http_client.execute_aql(
                query, bind_vars={"app_type": app_type} if app_type is not None else None,
            )
            return results if results else []
        except Exception as e:
            self.logger.error(f"❌ Get org apps failed: {str(e)}")
            if raise_on_error:
                raise
            return []

    # ==================== KB Apps Migration (legacy recordGroup -> app) ====================

    async def get_legacy_kb_record_groups(self, org_id: str) -> list[dict]:
        """Get every legacy KB stored as a recordGroups document for this org."""
        try:
            query = f"""
            FOR rg IN {CollectionNames.RECORD_GROUPS.value}
                FILTER rg.orgId == @org_id
                FILTER rg.groupType == @kb_type AND rg.connectorName == @kb_type
                RETURN rg
            """
            results = await self.execute_query(
                query,
                bind_vars={"org_id": org_id, "kb_type": Connectors.KNOWLEDGE_BASE.value},
            )
            return results if results else []
        except Exception as e:
            self.logger.error(f"❌ Get legacy KB record groups failed: {str(e)}")
            return []

    async def migrate_legacy_relation_edge(
        self,
        legacy_collection: str,
        legacy_relationship_type: str,
    ) -> dict:
        """Rename the hierarchy edge collection. ArangoDB updates the named graph's
        edge definitions itself; `legacy_relationship_type` is Neo4j's half.

        Both collections can exist: another service's `ensure_schema()` may create
        an empty one under the new name while the edges still sit under the old
        one, and a plain rename would fail on the taken name.
        """
        current = CollectionNames.NODE_RELATIONS.value
        try:
            legacy_exists = await self.http_client.collection_exists(legacy_collection)
            current_exists = await self.http_client.collection_exists(current)

            if not legacy_exists:
                return {"migrated": 0, "already_current": True}

            if not current_exists:
                if not await self.http_client.rename_collection(legacy_collection, current):
                    raise Exception(
                        f"Could not rename '{legacy_collection}' to '{current}'"
                    )
                count = await self.execute_query(
                    "RETURN LENGTH(@@edges)", bind_vars={"@edges": current}
                )
                migrated = (count or [0])[0] or 0
                self.logger.info(
                    f"Renamed '{legacy_collection}' to '{current}' ({migrated} edge(s))"
                )
                return {"migrated": migrated, "already_current": False}

            # Both exist: fold the legacy edges into the current collection,
            # keeping _key so a re-run cannot duplicate them, then drop it.
            moved = await self.execute_query(
                "LET moved = ("
                "  FOR e IN @@legacy"
                "    INSERT UNSET(e, '_id', '_rev') INTO @@current"
                "    OPTIONS { overwriteMode: 'replace' }"
                "    RETURN 1"
                ") RETURN LENGTH(moved)",
                bind_vars={"@legacy": legacy_collection, "@current": current},
            )
            migrated = (moved or [0])[0] or 0
            # ArangoDB refuses to drop a collection a graph still names.
            if not await self.http_client.remove_edge_definition(
                GraphNames.KNOWLEDGE_GRAPH.value, legacy_collection
            ):
                raise Exception(
                    f"Moved {migrated} edge(s) but could not take '{legacy_collection}' out of the graph"
                )
            if not await self.http_client.delete_collection(legacy_collection):
                raise Exception(f"Moved {migrated} edge(s) but could not drop '{legacy_collection}'")
            self.logger.info(
                f"Merged {migrated} edge(s) from '{legacy_collection}' into '{current}'"
            )
            return {"migrated": migrated, "already_current": False}

        except Exception as e:
            self.logger.error(f"❌ Legacy relation edge migration failed: {str(e)}")
            raise

    async def migrate_legacy_kb_to_app(
        self,
        kb_record_group: dict,
        org_id: str,
        resolved_creator_key: str | None,
    ) -> dict:
        """Migrate a single legacy KB recordGroup to its own apps document,
        reusing the same key. Arango documents are bound to their collection
        (no in-place "recollection"), so this recreates the doc in `apps`,
        retargets every PERMISSION/BELONGS_TO/INHERIT_PERMISSIONS edge that
        pointed at the old recordGroup, updates every record's connectorId,
        and deletes the old recordGroup doc + its own outbound belongsTo
        edge to the legacy shared hub app.
        """
        kb_key = kb_record_group.get("_key") or kb_record_group.get("id")
        if not kb_key:
            return {"success": False, "reason": "Legacy KB record group missing _key/id"}

        txn_id = None
        try:
            txn_id = await self.begin_transaction(
                read=[],
                write=[
                    CollectionNames.APPS.value,
                    CollectionNames.RECORD_GROUPS.value,
                    CollectionNames.ORG_APP_RELATION.value,
                    CollectionNames.USER_APP_RELATION.value,
                    CollectionNames.PERMISSION.value,
                    CollectionNames.BELONGS_TO.value,
                    CollectionNames.INHERIT_PERMISSIONS.value,
                    CollectionNames.RECORDS.value,
                ],
            )

            timestamp = get_epoch_timestamp_in_ms()
            name = kb_record_group.get("groupName") or "Untitled"
            created_by = resolved_creator_key or kb_record_group.get("createdBy")
            created_at = kb_record_group.get("createdAtTimestamp") or timestamp
            updated_at = kb_record_group.get("updatedAtTimestamp") or timestamp

            # 1. Create the new app doc, reusing the same key the recordGroup had.
            kb_data = {
                "id": kb_key,
                "createdBy": created_by,
                "orgId": org_id,
                "name": name,
                "type": Connectors.KNOWLEDGE_BASE.value,
                "appGroup": AppGroups.LOCAL_STORAGE.value,
                "authType": "NONE",
                "scope": ConnectorScopes.PERSONAL.value,
                "isActive": True,
                "isAgentActive": True,
                "isConfigured": True,
                "isAuthenticated": True,
                "vectorMembershipBackfilled": False,
                "hideConnector": True,
                "createdAtTimestamp": created_at,
                "updatedAtTimestamp": updated_at,
            }
            await self.batch_upsert_nodes([kb_data], CollectionNames.APPS.value, transaction=txn_id)

            # 2. Fetch every edge pointing at (or from) the old recordGroup that needs retargeting/removal.
            old_rg_id = f"{CollectionNames.RECORD_GROUPS.value}/{kb_key}"
            fetch_query = f"""
            RETURN {{
                permission: (FOR e IN {CollectionNames.PERMISSION.value} FILTER e._to == @old_rg_id RETURN e),
                belongs_to_in: (FOR e IN {CollectionNames.BELONGS_TO.value} FILTER e._to == @old_rg_id RETURN e),
                inherit_permissions_in: (FOR e IN {CollectionNames.INHERIT_PERMISSIONS.value} FILTER e._to == @old_rg_id RETURN e),
                belongs_to_out: (FOR e IN {CollectionNames.BELONGS_TO.value} FILTER e._from == @old_rg_id RETURN e)
            }}
            """
            edge_results = await self.execute_query(
                fetch_query, bind_vars={"old_rg_id": old_rg_id}, transaction=txn_id
            )
            edges = edge_results[0] if edge_results else {}

            def _split(full_id: str) -> tuple[str, str]:
                collection, key = full_id.split("/", 1)
                return collection, key

            async def _retarget(edge_list: list[dict], edge_collection: str) -> None:
                new_edges = []
                for e in edge_list:
                    from_collection, from_key = _split(e["_from"])
                    props = {k: v for k, v in e.items() if not k.startswith("_")}
                    new_edges.append({
                        "from_id": from_key,
                        "from_collection": from_collection,
                        "to_id": kb_key,
                        "to_collection": CollectionNames.APPS.value,
                        **props,
                    })
                if new_edges:
                    await self.batch_create_edges(new_edges, edge_collection, transaction=txn_id)
                for e in edge_list:
                    from_collection, from_key = _split(e["_from"])
                    await self.delete_edge(
                        from_id=from_key,
                        from_collection=from_collection,
                        to_id=kb_key,
                        to_collection=CollectionNames.RECORD_GROUPS.value,
                        collection=edge_collection,
                        transaction=txn_id,
                    )

            await _retarget(edges.get("permission", []), CollectionNames.PERMISSION.value)
            await _retarget(edges.get("belongs_to_in", []), CollectionNames.BELONGS_TO.value)
            await _retarget(edges.get("inherit_permissions_in", []), CollectionNames.INHERIT_PERMISSIONS.value)

            # 3. Delete the recordGroup's own outbound belongsTo edge (-> legacy shared hub app).
            for e in edges.get("belongs_to_out", []):
                to_collection, to_key = _split(e["_to"])
                await self.delete_edge(
                    from_id=kb_key,
                    from_collection=CollectionNames.RECORD_GROUPS.value,
                    to_id=to_key,
                    to_collection=to_collection,
                    collection=CollectionNames.BELONGS_TO.value,
                    transaction=txn_id,
                )

            # 4. Bulk-update every record belonging to this KB: connectorId -> kb_key
            # (was the legacy shared hub app id; externalGroupId/externalRootGroupId
            # already equal kb_key and are left unchanged).
            update_records_query = f"""
            FOR r IN {CollectionNames.RECORDS.value}
                FILTER r.externalGroupId == @kb_key
                UPDATE r WITH {{connectorId: @kb_key}} IN {CollectionNames.RECORDS.value}
            """
            await self.execute_query(update_records_query, bind_vars={"kb_key": kb_key}, transaction=txn_id)

            # 5. Delete the old recordGroup document.
            delete_rg_query = f"""
            REMOVE @kb_key IN {CollectionNames.RECORD_GROUPS.value}
            """
            await self.execute_query(delete_rg_query, bind_vars={"kb_key": kb_key}, transaction=txn_id)

            # 6. Create the new orgAppRelation + (if resolvable) userAppRelation edges.
            # orgAppRelation is validated against basic_edge_schema
            # (additionalProperties: False — only _from/_to/createdAtTimestamp
            # allowed), so no entityType/updatedAtTimestamp here.
            org_app_edge = {
                "from_id": org_id,
                "from_collection": CollectionNames.ORGS.value,
                "to_id": kb_key,
                "to_collection": CollectionNames.APPS.value,
                "createdAtTimestamp": timestamp,
            }
            await self.batch_create_edges([org_app_edge], CollectionNames.ORG_APP_RELATION.value, transaction=txn_id)

            if resolved_creator_key:
                # userAppRelation is validated against user_app_relation_schema,
                # which requires syncState/lastSyncUpdate — same convention as
                # every other connector's user-app edge.
                user_app_edge = {
                    "from_id": resolved_creator_key,
                    "from_collection": CollectionNames.USERS.value,
                    "to_id": kb_key,
                    "to_collection": CollectionNames.APPS.value,
                    "syncState": "NOT_STARTED",
                    "lastSyncUpdate": timestamp,
                    "createdAtTimestamp": timestamp,
                    "updatedAtTimestamp": timestamp,
                }
                await self.batch_create_edges([user_app_edge], CollectionNames.USER_APP_RELATION.value, transaction=txn_id)

            # 7. Safety net: verify at least one OWNER permission edge exists on the new app.
            owner_check_query = f"""
            FOR e IN {CollectionNames.PERMISSION.value}
                FILTER e._to == @new_app_id AND e.role == "OWNER"
                LIMIT 1
                RETURN 1
            """
            owner_check = await self.execute_query(
                owner_check_query,
                bind_vars={"new_app_id": f"{CollectionNames.APPS.value}/{kb_key}"},
                transaction=txn_id,
            )
            if not owner_check:
                self.logger.warning(
                    f"⚠️ Migrated KB {kb_key} has no OWNER permission edge (degenerate legacy data)"
                )

            await self.commit_transaction(txn_id)
            return {"success": True}

        except Exception as e:
            self.logger.error(f"❌ Failed to migrate legacy KB {kb_key} to app: {str(e)}")
            if txn_id is not None:
                try:
                    await self.rollback_transaction(txn_id)
                except Exception as rb_err:
                    self.logger.warning(f"Rollback failed for KB {kb_key}: {rb_err}")
            return {"success": False, "reason": str(e)}

    async def count_legacy_kb_record_groups(self, org_id: str) -> int:
        """Count remaining legacy KB recordGroups for this org. Returns -1 on
        error so callers treat "unknown" as "not safe to clean up", distinct
        from a genuine 0.
        """
        try:
            query = f"""
            FOR rg IN {CollectionNames.RECORD_GROUPS.value}
                FILTER rg.orgId == @org_id
                FILTER rg.groupType == @kb_type AND rg.connectorName == @kb_type
                COLLECT WITH COUNT INTO total
                RETURN total
            """
            results = await self.execute_query(
                query, bind_vars={"org_id": org_id, "kb_type": Connectors.KNOWLEDGE_BASE.value}
            )
            return results[0] if results else 0
        except Exception as e:
            self.logger.error(f"❌ Count legacy KB record groups failed: {str(e)}")
            return -1

    async def delete_kb_hub_app(self, org_id: str) -> bool:
        """Delete the org's legacy shared KB hub app plus its orgAppRelation/
        userAppRelation edges. Only call once count_legacy_kb_record_groups
        returns 0. Safety-checks for lingering references before deleting.
        """
        hub_app_key = f"knowledgeBase_{org_id}"
        hub_app_id = f"{CollectionNames.APPS.value}/{hub_app_key}"
        try:
            safety_query = f"""
            RETURN {{
                belongs_to_refs: LENGTH(FOR e IN {CollectionNames.BELONGS_TO.value} FILTER e._to == @hub_app_id LIMIT 1 RETURN 1),
                permission_refs: LENGTH(FOR e IN {CollectionNames.PERMISSION.value} FILTER e._to == @hub_app_id LIMIT 1 RETURN 1)
            }}
            """
            safety_results = await self.execute_query(safety_query, bind_vars={"hub_app_id": hub_app_id})
            safety = safety_results[0] if safety_results else {}
            if safety.get("belongs_to_refs") or safety.get("permission_refs"):
                self.logger.error(
                    f"❌ Refusing to delete legacy KB hub app {hub_app_key}: still referenced by belongsTo/permission edges"
                )
                return False

            org_edge_query = f"""
            FOR e IN {CollectionNames.ORG_APP_RELATION.value}
                FILTER e._to == @hub_app_id
                RETURN e
            """
            org_edges = await self.execute_query(org_edge_query, bind_vars={"hub_app_id": hub_app_id})
            for e in org_edges or []:
                from_collection, from_key = e["_from"].split("/", 1)
                await self.delete_edge(
                    from_id=from_key,
                    from_collection=from_collection,
                    to_id=hub_app_key,
                    to_collection=CollectionNames.APPS.value,
                    collection=CollectionNames.ORG_APP_RELATION.value,
                )

            user_edge_query = f"""
            FOR e IN {CollectionNames.USER_APP_RELATION.value}
                FILTER e._to == @hub_app_id
                RETURN e
            """
            user_edges = await self.execute_query(user_edge_query, bind_vars={"hub_app_id": hub_app_id})
            for e in user_edges or []:
                from_collection, from_key = e["_from"].split("/", 1)
                await self.delete_edge(
                    from_id=from_key,
                    from_collection=from_collection,
                    to_id=hub_app_key,
                    to_collection=CollectionNames.APPS.value,
                    collection=CollectionNames.USER_APP_RELATION.value,
                )

            delete_query = f"""
            FOR app IN {CollectionNames.APPS.value}
                FILTER app._key == @hub_app_key
                REMOVE app IN {CollectionNames.APPS.value}
            """
            await self.execute_query(delete_query, bind_vars={"hub_app_key": hub_app_key})
            return True
        except Exception as e:
            self.logger.error(f"❌ Failed to delete legacy KB hub app for org {org_id}: {str(e)}")
            return False

    @staticmethod
    def _extract_legacy_record_group_ids(raw_filters: Any) -> list[str] | None:
        """Parse a legacy KB knowledge entry's `filters` (stringified JSON or
        dict) and return its `recordGroups` id list, or None if absent/empty
        (meaning "no restriction — search every KB", the pre-migration
        equivalent of today's per-KB-app knowledge entries).
        """
        if not raw_filters:
            return None
        try:
            parsed = json.loads(raw_filters) if isinstance(raw_filters, str) else raw_filters
        except (ValueError, TypeError):
            return None
        if not isinstance(parsed, dict):
            return None
        record_groups = parsed.get("recordGroups")
        if not isinstance(record_groups, list):
            return None
        ids = [g for g in record_groups if isinstance(g, str) and g]
        return ids or None

    async def migrate_agent_hub_knowledge(self, org_id: str) -> dict:
        """Expand agent knowledge sources still pointing at the legacy shared
        KB hub app into one source per current per-KB app for this org.
        AgentKnowledge documents reference apps via a plain `connectorId`
        string, not a graph edge, so migrate_legacy_kb_to_app never touches
        them — this must run separately, before delete_kb_hub_app.
        """
        hub_app_key = f"knowledgeBase_{org_id}"
        try:
            target_query = f"""
            FOR app IN {CollectionNames.APPS.value}
                FILTER app.orgId == @org_id AND app.type == "KB" AND app._key != @hub_app_key
                RETURN app._key
            """
            target_kb_app_ids = await self.execute_query(
                target_query, bind_vars={"org_id": org_id, "hub_app_key": hub_app_key}
            )
            target_kb_app_ids = target_kb_app_ids or []
            if not target_kb_app_ids:
                return {"agents_migrated": 0, "knowledge_nodes_created": 0}

            find_query = f"""
            FOR a IN {CollectionNames.AGENT_INSTANCES.value}
                FILTER a.orgId == @org_id
                FOR e IN {CollectionNames.AGENT_HAS_KNOWLEDGE.value}
                    FILTER e._from == a._id
                    LET ak = DOCUMENT(e._to)
                    FILTER ak != null AND ak.connectorId == @hub_app_key
                    LET existing = (
                        FOR e2 IN {CollectionNames.AGENT_HAS_KNOWLEDGE.value}
                            FILTER e2._from == a._id
                            LET other = DOCUMENT(e2._to)
                            FILTER other != null AND other.connectorId != null
                            RETURN other.connectorId
                    )
                    RETURN {{ agent_key: a._key, knowledge_key: ak._key, filters: ak.filters, existing_connector_ids: existing }}
            """
            rows = await self.execute_query(
                find_query, bind_vars={"org_id": org_id, "hub_app_key": hub_app_key}
            )
            if not rows:
                return {"agents_migrated": 0, "knowledge_nodes_created": 0}

            timestamp = get_epoch_timestamp_in_ms()
            agents_migrated = 0
            knowledge_nodes_created = 0
            target_kb_app_ids_set = set(target_kb_app_ids)

            for row in rows:
                agent_key = row.get("agent_key")
                old_knowledge_key = row.get("knowledge_key")
                if not agent_key or not old_knowledge_key:
                    continue
                existing = set(row.get("existing_connector_ids") or [])

                # Pre-migration, every KB knowledge entry pointed at the shared
                # hub (connectorId), and the *actual* per-collection scope (if
                # any) lived in filters.recordGroups — an empty/absent list
                # meant "no restriction, search every KB". Since
                # migrate_legacy_kb_to_app reuses each recordGroup's own key
                # as its new app key, those ids map directly onto
                # target_kb_app_ids. Only fall back to "every current KB" when
                # the original entry truly had no restriction — otherwise this
                # would silently widen the agent's access beyond what was
                # originally selected.
                scoped_kb_ids = self._extract_legacy_record_group_ids(row.get("filters"))
                if scoped_kb_ids:
                    expand_targets = [kb_id for kb_id in scoped_kb_ids if kb_id in target_kb_app_ids_set]
                else:
                    expand_targets = target_kb_app_ids

                new_nodes = []
                new_edges = []
                for kb_app_id in expand_targets:
                    if kb_app_id in existing:
                        continue
                    knowledge_key = str(uuid.uuid4())
                    new_nodes.append({
                        "_key": knowledge_key,
                        "connectorId": kb_app_id,
                        "filters": "{}",
                        "createdAtTimestamp": timestamp,
                        "updatedAtTimestamp": timestamp,
                    })
                    new_edges.append({
                        "from_id": agent_key,
                        "from_collection": CollectionNames.AGENT_INSTANCES.value,
                        "to_id": knowledge_key,
                        "to_collection": CollectionNames.AGENT_KNOWLEDGE.value,
                        "createdAtTimestamp": timestamp,
                        "updatedAtTimestamp": timestamp,
                    })

                if new_nodes:
                    await self.batch_upsert_nodes(new_nodes, CollectionNames.AGENT_KNOWLEDGE.value)
                    await self.batch_create_edges(new_edges, CollectionNames.AGENT_HAS_KNOWLEDGE.value)
                    knowledge_nodes_created += len(new_nodes)

                await self.delete_edge(
                    from_id=agent_key,
                    from_collection=CollectionNames.AGENT_INSTANCES.value,
                    to_id=old_knowledge_key,
                    to_collection=CollectionNames.AGENT_KNOWLEDGE.value,
                    collection=CollectionNames.AGENT_HAS_KNOWLEDGE.value,
                )
                await self.delete_nodes([old_knowledge_key], CollectionNames.AGENT_KNOWLEDGE.value)
                agents_migrated += 1

            return {"agents_migrated": agents_migrated, "knowledge_nodes_created": knowledge_nodes_created}
        except Exception as e:
            self.logger.error(f"❌ Failed to migrate agent hub knowledge for org {org_id}: {str(e)}")
            return {"agents_migrated": 0, "knowledge_nodes_created": 0, "error": str(e)}

    async def get_departments(
        self,
        org_id: str | None = None,
        transaction: str | None = None
    ) -> list[str]:
        """
        Get all departments that either have no org_id or match the given org_id.

        Args:
            org_id (Optional[str]): Organization ID to filter departments
            transaction (Optional[str]): Optional transaction ID

        Returns:
            List[str]: List of department names
        """
        try:
            if org_id:
                query = f"""
                FOR department IN {CollectionNames.DEPARTMENTS.value}
                    FILTER department.orgId == null OR department.orgId == @org_id
                    RETURN department.departmentName
                """
                bind_vars = {"org_id": org_id}
            else:
                query = f"""
                FOR department IN {CollectionNames.DEPARTMENTS.value}
                    RETURN department.departmentName
                """
                bind_vars = {}

            results = await self.http_client.execute_aql(query, bind_vars, txn_id=transaction)
            return list(results) if results else []
        except Exception as e:
            self.logger.error(f"❌ Get departments failed: {str(e)}")
            return []

    async def update_queued_duplicates_status(
        self,
        record_id: str,
        new_indexing_status: str,
        virtual_record_id: str | None = None,
        transaction: str | None = None,
        reason: str | None = None,
    ) -> int:
        """
        Find all QUEUED duplicate records with the same md5 hash and update their status.
        Works with all record types by querying the RECORDS collection directly.

        Args:
            record_id (str): The record ID to use as reference for finding duplicates
            new_indexing_status (str): The new indexing status to set
            virtual_record_id (Optional[str]): The virtual record ID to set on duplicates
            transaction (Optional[str]): Optional transaction ID

        Returns:
            int: Number of records updated
        """
        try:
            self.logger.debug(
                f"🔍 Finding QUEUED duplicate records for record {record_id}"
            )

            # First get the record info for the reference record
            record_query = f"""
            FOR record IN {CollectionNames.RECORDS.value}
                FILTER record._key == @record_id
                RETURN record
            """

            results = await self.http_client.execute_aql(
                record_query,
                bind_vars={"record_id": record_id},
                txn_id=transaction
            )

            ref_record = None
            if results:
                with contextlib.suppress(IndexError, StopIteration):
                    ref_record = results[0]
            if not ref_record:
                self.logger.debug(f"No record found for {record_id}, skipping queued duplicate update")
                return 0

            md5_checksum = ref_record.get("md5Checksum")
            size_in_bytes = ref_record.get("sizeInBytes")
            org_id = ref_record.get("orgId")

            if not md5_checksum:
                # Expected, not a fault: duplicates are matched by md5Checksum
                # alone, so a record without one (a folder, or anything with no
                # content) can have none waiting on it. Warning-level here fires
                # once per such record and drowns real problems.
                self.logger.debug(f"Record {record_id} missing md5Checksum")
                return 0

            # QUEUED is also every new record's initial status, so without the
            # org scope another org's unindexed copy would be marked done with
            # this org's virtualRecordId. No orgId fails closed, as dedup does.
            if not org_id:
                self.logger.debug(f"Record {record_id} missing orgId, skipping queued duplicate update")
                return 0

            extraction_status = promoted_duplicate_extraction_status(
                new_indexing_status, ref_record
            )
            if extraction_status is None:
                self.logger.info(
                    "Record %s is indexed but its enrichment has not ended; its queued duplicates wait",
                    record_id,
                )
                return 0

            # Find all queued duplicate records directly from RECORDS collection
            query = f"""
            FOR record IN {CollectionNames.RECORDS.value}
                FILTER record.md5Checksum == @md5_checksum
                AND record._key != @record_id
                AND record.indexingStatus == @queued_status
                AND record.orgId == @org_id
                AND {aql_live_record("record")}
            """

            bind_vars = {
                "md5_checksum": md5_checksum,
                "record_id": record_id,
                "queued_status": "QUEUED",
                "org_id": org_id,
            }

            if size_in_bytes is not None:
                query += """
                AND record.sizeInBytes == @size_in_bytes
                """
                bind_vars["size_in_bytes"] = size_in_bytes

            query += """
                RETURN record
            """

            results = await self.http_client.execute_aql(
                query,
                bind_vars=bind_vars,
                txn_id=transaction
            )

            queued_records = list(results) if results else []

            if not queued_records:
                self.logger.debug("✅ No QUEUED duplicate records found")
                return 0

            self.logger.info(
                f"✅ Found {len(queued_records)} QUEUED duplicate record(s) to update"
            )

            # Update all queued records
            current_timestamp = get_epoch_timestamp_in_ms()
            updated_records = []

            for queued_record in queued_records:
                doc = dict(queued_record)
                record_key = doc.get("_key") or doc.get("id")
                if not record_key:
                    continue

                dup_update = {
                    "id": record_key,
                    "indexingStatus": new_indexing_status,
                    "lastIndexTimestamp": current_timestamp,
                    "isDirty": False,
                    "virtualRecordId": virtual_record_id,
                    "extractionStatus": extraction_status,
                }
                if reason:
                    dup_update["reason"] = reason
                updated_records.append(dup_update)

            if not updated_records:
                return 0

            # Same batch as the promotion: a crash after it would otherwise
            # leave the duplicates COMPLETED with no taxonomy and nothing to
            # trigger the copy, since a redelivery finds nothing QUEUED. Only
            # an indexed primary has anything to copy.
            if new_indexing_status in _RECONCILED_STATUSES:
                updated_records.append({
                    "id": record_id,
                    DUPLICATE_RECONCILE_PENDING_FIELD: True,
                    DUPLICATE_RECONCILE_ATTEMPTS_FIELD: 0,
                    DUPLICATE_RECONCILE_DUE_AT_FIELD: current_timestamp + DUPLICATE_RECONCILE_GRACE_MS,
                })

            success = await self.batch_update_nodes(
                updated_records, CollectionNames.RECORDS.value, transaction
            )
            if not success:
                self.logger.warning(
                    "⚠️ Failed to update queued duplicate records for %s - some records may not exist",
                    record_id,
                )
                return -1

            self.logger.debug(
                f"✅ Successfully updated {len(queued_records)} QUEUED duplicate record(s) to status {new_indexing_status}"
            )

            return len(queued_records)

        except Exception as e:
            self.logger.error(
                f"❌ Failed to update queued duplicates status: {str(e)}"
            )
            return -1

    async def batch_upsert_record_permissions(
        self,
        record_id: str,
        permissions: list[dict],
        transaction: str | None = None
    ) -> None:
        """Batch upsert record permissions"""
        try:
            if not permissions:
                return

            await self.batch_create_edges(
                permissions,
                collection=CollectionNames.PERMISSION.value,
                transaction=transaction
            )

        except Exception as e:
            self.logger.error(f"❌ Batch upsert record permissions failed: {str(e)}")
            raise

    async def get_first_user_with_permission_to_node(
        self,
        node_id: str,
        node_collection: str,
        transaction: str | None = None
    ) -> User | None:
        """
        Get first user with permission to node.

        Args:
            node_id: The node ID
            node_collection: The node collection name
            transaction: Optional transaction ID

        Returns:
            Optional[User]: User with permission to the node, or None if not found
        """
        try:
            # Construct ArangoDB-specific _to value
            node_key = f"{node_collection}/{node_id}"

            query = """
            FOR vertex IN 0..8 OUTBOUND @node_key @@inherit_collection
                FOR edge IN @@edge_collection
                    FILTER edge._to == vertex._id
                    FOR user IN @@user_collection
                        FILTER user._id == edge._from
                        LIMIT 1
                        RETURN user
            """
            bind_vars = {
                "@inherit_collection": CollectionNames.INHERIT_PERMISSIONS.value,
                "@edge_collection": CollectionNames.PERMISSION.value,
                "@user_collection": CollectionNames.USERS.value,
                "node_key": node_key
            }

            results = await self.http_client.execute_aql(query, bind_vars, transaction)
            if results:
                user_data = self._translate_node_from_arango(results[0])
                return User.from_arango_user(user_data)
            return None

        except Exception as e:
            self.logger.error(f"❌ Get first user with permission to node failed: {str(e)}")
            return None

    async def get_users_with_permission_to_node(
        self,
        node_id: str,
        node_collection: str,
        transaction: str | None = None,
        *,
        raise_on_error: bool = False,
    ) -> list[User]:
        """
        Get all users with permission to node.

        Args:
            node_id: The node ID
            node_collection: The node collection name
            transaction: Optional transaction ID

        Returns:
            List[User]: List of users with permission to the node
        """
        try:
            # Construct ArangoDB-specific _to value
            node_key = f"{node_collection}/{node_id}"

            query = """
            FOR vertex IN 0..8 OUTBOUND @node_key @@inherit_collection
                FOR edge IN @@edge_collection
                    FILTER edge._to == vertex._id
                    FOR user IN @@user_collection
                        FILTER user._id == edge._from
                        RETURN DISTINCT user
            """
            bind_vars = {
                "@inherit_collection": CollectionNames.INHERIT_PERMISSIONS.value,
                "@edge_collection": CollectionNames.PERMISSION.value,
                "@user_collection": CollectionNames.USERS.value,
                "node_key": node_key
            }

            results = await self.http_client.execute_aql(query, bind_vars, transaction)
            return [User.from_arango_user(self._translate_node_from_arango(result)) for result in results]

        except Exception as e:
            self.logger.error(f"❌ Get users with permission to node failed: {str(e)}")
            if raise_on_error:
                raise
            return []

    async def get_groups_with_permission_to_node(
        self,
        node_id: str,
        node_collection: str,
        transaction: str | None = None,
        *,
        raise_on_error: bool = False,
    ) -> list[AppUserGroup]:
        """Get the user groups with a permission edge to a node."""
        try:
            query = """
            FOR edge IN @@edge_collection
                FILTER edge._to == @node_key
                FOR user_group IN @@group_collection
                    FILTER user_group._id == edge._from AND user_group.externalGroupId != null
                    RETURN DISTINCT user_group
            """
            bind_vars = {
                "@edge_collection": CollectionNames.PERMISSION.value,
                "@group_collection": CollectionNames.GROUPS.value,
                "node_key": f"{node_collection}/{node_id}",
            }

            results = await self.http_client.execute_aql(query, bind_vars, transaction)
            return [
                AppUserGroup.from_arango_base_user_group(self._translate_node_from_arango(result))
                for result in results
            ]

        except Exception as e:
            self.logger.error(f"❌ Get groups with permission to node failed: {str(e)}")
            if raise_on_error:
                raise
            return []

    async def get_record_owner_source_user_email(
        self,
        record_id: str,
        transaction: str | None = None,
        *,
        raise_on_error: bool = False,
    ) -> str | None:
        """Get record owner source user email"""
        try:
            query = f"""
            FOR vertex IN 0..8 OUTBOUND CONCAT('{CollectionNames.RECORDS.value}/', @record_id) {CollectionNames.INHERIT_PERMISSIONS.value}
                FOR edge IN {CollectionNames.PERMISSION.value}
                    FILTER edge._to == vertex._id
                    FILTER edge.role == 'OWNER'
                    FILTER edge.type == 'USER'
                    LET user_key = SPLIT(edge._from, '/')[1]
                    LET user = DOCUMENT('{CollectionNames.USERS.value}', user_key)
                    LIMIT 1
                    RETURN user.email
            """
            bind_vars = {
                "record_id": record_id
            }

            results = await self.http_client.execute_aql(query, bind_vars, transaction)
            return results[0] if results else None

        except Exception as e:
            self.logger.error(f"❌ Get record owner source user email failed: {str(e)}")
            if raise_on_error:
                raise
            return None

    async def get_sync_point(
        self,
        key: str,
        collection: str,
        transaction: str | None = None,
        *,
        raise_on_error: bool = False,
    ) -> dict | None:
        """
        Get sync point by syncPointKey field.
        """
        try:
            query = """
            FOR doc IN @@collection
                FILTER doc.syncPointKey == @key
                LIMIT 1
                RETURN doc
            """
            bind_vars = {
                "@collection": collection,
                "key": key
            }

            results = await self.http_client.execute_aql(query, bind_vars, transaction)
            return results[0] if results else None

        except Exception as e:
            self.logger.error(f"❌ Get sync point failed: {str(e)}")
            if raise_on_error:
                raise
            return None

    async def upsert_sync_point(
        self,
        sync_point_key: str,
        sync_point_data: dict,
        collection: str,
        transaction: str | None = None
    ) -> bool:
        """
        Upsert sync point by syncPointKey field.
        """
        try:
            # First check if document exists
            # Raising: a read that failed must not answer "no row here", which
            # would insert a second sync point for this key and leave the two
            # of them racing to be the one LIMIT 1 returns.
            existing = await self.get_sync_point(
                sync_point_key, collection, transaction, raise_on_error=True
            )

            if existing:
                # Update existing document
                query = """
                FOR doc IN @@collection
                    FILTER doc.syncPointKey == @key
                    UPDATE doc WITH @data IN @@collection
                    RETURN NEW
                """
                bind_vars = {
                    "@collection": collection,
                    "key": sync_point_key,
                    "data": {
                        **sync_point_data,
                        "syncPointKey": sync_point_key,
                        "updatedAtTimestamp": get_epoch_timestamp_in_ms()
                    }
                }
            else:
                # Insert new document
                query = """
                INSERT @doc INTO @@collection
                RETURN NEW
                """
                bind_vars = {
                    "@collection": collection,
                    "doc": {
                        **sync_point_data,
                        "syncPointKey": sync_point_key,
                        "updatedAtTimestamp": get_epoch_timestamp_in_ms()
                    }
                }

            await self.http_client.execute_aql(query, bind_vars, transaction)
            return True

        except Exception as e:
            self.logger.error(f"❌ Upsert sync point failed: {str(e)}")
            raise

    async def remove_sync_point(
        self,
        key: str,
        collection: str,
        transaction: str | None = None
    ) -> None:
        """
        Remove sync point by syncPointKey field.
        """
        try:
            query = """
            FOR doc IN @@collection
                FILTER doc.syncPointKey == @key
                REMOVE doc IN @@collection
            """
            bind_vars = {
                "@collection": collection,
                "key": key
            }

            await self.http_client.execute_aql(query, bind_vars, transaction)

        except Exception as e:
            self.logger.error(f"❌ Remove sync point failed: {str(e)}")
            raise

    async def batch_upsert_app_users(
        self,
        users: list[AppUser],
        transaction: str | None = None
    ) -> None:
        """
        Batch upsert app users.

        Creates users if they don't exist, creates org relation and user-app relation.
        """
        try:
            if not users:
                return

            # Get org_id
            orgs = await self.get_all_orgs()
            if not orgs:
                raise Exception("No organizations found in the database")
            org_id = orgs[0]["_key"]
            connector_id = users[0].connector_id

            app = await self.get_document(connector_id, CollectionNames.APPS.value)
            if not app:
                raise Exception(f"Failed to get/create app: {connector_id}")

            app_id = app["_id"]

            for user in users:
                # Check if user exists
                user_record = await self.get_user_by_email(user.email, transaction)
                is_new = not user_record

                if is_new:
                    # Create new user
                    await self.batch_upsert_nodes(
                        [{**user.to_arango_base_user(), "orgId": org_id, "isActive": False}],
                        collection=CollectionNames.USERS.value,
                        transaction=transaction
                    )

                    user_record = await self.get_user_by_email(user.email, transaction)

                    # This address may already exist as a Person from an external share.
                    # Non-fatal: one CRM contact must not fail a whole sync.
                    try:
                        await self.migrate_person_to_user(
                            user.email, user.id, org_id, transaction=transaction
                        )
                    except Exception as migrate_err:
                        self.logger.error(
                            f"❌ Person adoption failed for {user.email}: {migrate_err}"
                        )

                # A guest is an org member like anyone else: other connectors resolve
                # group members through that edge. The gate edge below is what keeps
                # this connector's org-wide grants from them. An earlier version
                # deleted a synced guest's org edge, so an existing guest gets it back.
                if is_new or user.is_guest:
                    user_org_relation = {
                        "_from": f"{CollectionNames.USERS.value}/{user_record.id}",
                        "_to": f"{CollectionNames.ORGS.value}/{org_id}",
                        "createdAtTimestamp": user.created_at,
                        "updatedAtTimestamp": user.updated_at,
                        "entityType": "ORGANIZATION",
                    }
                    await self.batch_create_edges(
                        [user_org_relation],
                        collection=CollectionNames.BELONGS_TO.value,
                        transaction=transaction
                    )

                # Create user-app relation
                user_key = user_record.id
                user_app_relation = {
                    "_from": f"{CollectionNames.USERS.value}/{user_key}",
                    "_to": app_id,
                    "sourceUserId": user.source_user_id,
                    # Always written, never omitted: it flags a source guest, and
                    # un-flags a member first seen as an external collaborator.
                    "isExternalUser": user.is_guest,
                    "syncState": "NOT_STARTED",
                    "lastSyncUpdate": get_epoch_timestamp_in_ms(),
                    "createdAtTimestamp": get_epoch_timestamp_in_ms(),
                    "updatedAtTimestamp": get_epoch_timestamp_in_ms(),
                }

                await self.batch_create_edges(
                    [user_app_relation],
                    collection=CollectionNames.USER_APP_RELATION.value,
                    transaction=transaction
                )

        except Exception as e:
            self.logger.error(f"❌ Batch upsert app users failed: {str(e)}")
            raise

    async def ensure_all_team_with_users(self, org_id: str) -> None:
        """
        Ensure the org's 'All' team exists and every active org user has a PERMISSION edge.

        Creates team node with id=all_{org_id} if missing, fetches all active users,
        and adds PERMISSION edges for users not already in the team.

        Idempotent, runs without transaction, safe to call multiple times.
        """
        try:
            team_key = f"all_{org_id}"
            ts = get_epoch_timestamp_in_ms()

            # 1. Create team node only if it doesn't exist
            existing_team = await self.get_document(team_key, CollectionNames.TEAMS.value)
            if not existing_team:
                team_node = {
                    "id": team_key,
                    "name": "All",
                    "description": "All organization members",
                    "createdBy": "system",
                    "orgId": org_id,
                    "createdAtTimestamp": ts,
                    "updatedAtTimestamp": ts,
                }
                await self.batch_upsert_nodes([team_node], CollectionNames.TEAMS.value)
                self.logger.debug(f"Created 'All' team for org {org_id}")

            # 2. Get all active users sorted by createdAtTimestamp ascending
            users = await self.get_users(org_id, active=True)
            if not users:
                self.logger.debug(f"No active users found for org {org_id}")
                return

            users_sorted = sorted(users, key=lambda u: u.get("createdAtTimestamp", 0))
            self.logger.debug(f"📊 Found {len(users_sorted)} active users for org {org_id}")

            # 3. Get current team members to determine if team is empty
            team_with_users = await self.get_team_with_users(team_id=team_key, user_key=None)
            existing_member_count = len((team_with_users or {}).get("members", []))
            owner_assigned = existing_member_count > 0

            self.logger.debug(f"📊 All team for org {org_id}: existing_member_count={existing_member_count}, owner_assigned={owner_assigned}")
            if team_with_users and team_with_users.get("members"):
                self.logger.debug(
                    "📊 Existing members: %s",
                    [
                        f"{m.get('userEmail') or '?'}:{m.get('role') or '?'}"
                        for m in team_with_users.get("members", [])
                    ],
                )

            # 4. Add each user without a PERMISSION edge
            for user in users_sorted:
                user_key = user.get("_key") or user.get("id")
                if not user_key:
                    continue

                existing_edge = await self.get_edge(
                    from_id=user_key,
                    from_collection=CollectionNames.USERS.value,
                    to_id=team_key,
                    to_collection=CollectionNames.TEAMS.value,
                    collection=CollectionNames.PERMISSION.value,
                )
                if existing_edge:
                    continue

                role = "OWNER" if not owner_assigned else "READER"
                self.logger.debug(f"📊 Assigning role {role} to user {user_key} (owner_assigned={owner_assigned})")

                if not owner_assigned:
                    owner_assigned = True
                    try:
                        await self.update_node(
                            team_key,
                            CollectionNames.TEAMS.value,
                            {"createdBy": user_key, "updatedAtTimestamp": ts},
                        )
                        self.logger.debug(f"✅ Updated team createdBy to {user_key}")
                    except Exception as e:
                        self.logger.warning(f"Failed to update createdBy for team {team_key}: {e}")

                permission_edge = {
                    "from_id": user_key,
                    "from_collection": CollectionNames.USERS.value,
                    "to_id": team_key,
                    "to_collection": CollectionNames.TEAMS.value,
                    "type": "USER",
                    "role": role,
                    "createdAtTimestamp": ts,
                    "updatedAtTimestamp": ts,
                }
                await self.batch_create_edges(
                    [permission_edge], CollectionNames.PERMISSION.value
                )
                self.logger.debug(f"✅ Added user {user_key} to All team with role {role}")

        except Exception as e:
            self.logger.error(f"ensure_all_team_with_users failed for org {org_id}: {e}", exc_info=True)
            raise

    async def add_user_to_all_team(self, org_id: str, user_key: str) -> None:
        """
        Add a specific user to the org's 'All' team with a PERMISSION edge.

        Ensures All team exists, checks if user already has PERMISSION edge,
        and adds it if missing. First user in team gets OWNER, subsequent get READER.

        Idempotent, safe to call multiple times for same user.
        """
        try:
            team_key = f"all_{org_id}"
            ts = get_epoch_timestamp_in_ms()

            # 1. Create team node only if it doesn't exist
            existing_team = await self.get_document(team_key, CollectionNames.TEAMS.value)
            if not existing_team:
                team_node = {
                    "id": team_key,
                    "name": "All",
                    "description": "All organization members",
                    "createdBy": "system",
                    "orgId": org_id,
                    "createdAtTimestamp": ts,
                    "updatedAtTimestamp": ts,
                }
                await self.batch_upsert_nodes([team_node], CollectionNames.TEAMS.value)
                self.logger.debug(f"Created 'All' team for org {org_id}")

            # 2. Check if this user already has a PERMISSION edge
            existing_edge = await self.get_edge(
                from_id=user_key,
                from_collection=CollectionNames.USERS.value,
                to_id=team_key,
                to_collection=CollectionNames.TEAMS.value,
                collection=CollectionNames.PERMISSION.value,
            )
            if existing_edge:
                self.logger.debug(f"User {user_key} already has PERMISSION edge to All team")
                return

            # 3. Check if team has any existing members to determine role
            team_with_users = await self.get_team_with_users(team_id=team_key, user_key=None)
            existing_member_count = len((team_with_users or {}).get("members", []))
            role = "OWNER" if existing_member_count == 0 else "READER"

            self.logger.debug(f"Assigning role {role} to user {user_key} (existing members: {existing_member_count})")

            # 4. If assigning first OWNER, update team.createdBy
            if role == "OWNER":
                try:
                    await self.update_node(
                        team_key,
                        CollectionNames.TEAMS.value,
                        {"createdBy": user_key, "updatedAtTimestamp": ts},
                    )
                    self.logger.debug(f"Updated team createdBy to {user_key}")
                except Exception as e:
                    self.logger.warning(f"Failed to update createdBy for team {team_key}: {e}")

            # 5. Create PERMISSION edge
            permission_edge = {
                "from_id": user_key,
                "from_collection": CollectionNames.USERS.value,
                "to_id": team_key,
                "to_collection": CollectionNames.TEAMS.value,
                "type": "USER",
                "role": role,
                "createdAtTimestamp": ts,
                "updatedAtTimestamp": ts,
            }
            await self.batch_create_edges(
                [permission_edge], CollectionNames.PERMISSION.value
            )
            self.logger.debug(f"Added user {user_key} to All team with role {role}")

        except Exception as e:
            self.logger.error(f"add_user_to_all_team failed for org {org_id}, user {user_key}: {e}", exc_info=True)
            raise

    async def ensure_team_app_edge(
        self,
        connector_id: str,
        org_id: str,
        transaction: Optional[str] = None
    ) -> None:
        """
        Ensure the org's "All" team has an edge to the app in userAppRelation.
        Idempotent: creates teams/all_{org_id} -> apps/{connector_id} if not present.
        """
        try:
            team_key = f"all_{org_id}"
            existing = await self.get_edge(
                from_id=team_key,
                from_collection=CollectionNames.TEAMS.value,
                to_id=connector_id,
                to_collection=CollectionNames.APPS.value,
                collection=CollectionNames.USER_APP_RELATION.value,
                transaction=transaction
            )
            if existing:
                return
            ts = get_epoch_timestamp_in_ms()
            edge = {
                "_from": f"{CollectionNames.TEAMS.value}/{team_key}",
                "_to": f"{CollectionNames.APPS.value}/{connector_id}",
                "sourceUserId": team_key,
                "syncState": "NOT_STARTED",
                "lastSyncUpdate": ts,
                "createdAtTimestamp": ts,
                "updatedAtTimestamp": ts,
            }
            await self.batch_create_edges(
                [edge],
                collection=CollectionNames.USER_APP_RELATION.value,
                transaction=transaction
            )
            self.logger.debug(f"Created team->app edge: teams/{team_key} -> apps/{connector_id}")
        except Exception as e:
            self.logger.error(f"ensure_team_app_edge failed: {e}", exc_info=True)
            raise

    async def upsert_authenticated_as(
        self,
        creator_key: str,
        source_user_key: str,
        connector_id: str,
        org_id: str,
        transaction: str | None = None,
    ) -> None:
        # _key = connector_id keeps exactly one link per connector instance; UPSERT repoints on re-auth.
        ts = get_epoch_timestamp_in_ms()
        query = f"""
        UPSERT {{ _key: @connectorId }}
        INSERT {{
            _key: @connectorId, _from: @from, _to: @to,
            connectorId: @connectorId, orgId: @orgId,
            createdAtTimestamp: @ts, updatedAtTimestamp: @ts
        }}
        UPDATE {{ _from: @from, _to: @to, orgId: @orgId, updatedAtTimestamp: @ts }}
        IN {CollectionNames.AUTHENTICATED_AS.value}
        """
        await self.execute_query(
            query,
            bind_vars={
                "connectorId": connector_id,
                "from": f"{CollectionNames.USERS.value}/{creator_key}",
                "to": f"{CollectionNames.USERS.value}/{source_user_key}",
                "orgId": org_id,
                "ts": ts,
            },
            transaction=transaction,
        )

    async def remove_authenticated_as(
        self,
        connector_id: str,
        transaction: str | None = None,
    ) -> bool:
        query = f"""
        FOR link IN {CollectionNames.AUTHENTICATED_AS.value}
            FILTER link._key == @connectorId
            REMOVE link IN {CollectionNames.AUTHENTICATED_AS.value}
            RETURN OLD._key
        """
        removed = await self.execute_query(query, bind_vars={"connectorId": connector_id}, transaction=transaction)
        return bool(removed)

