    async def delete_local_fs_record(
        self,
        record_id: str,
        user_id: str,
        record: dict,
        transaction: str | None = None,
        *,
        soft_delete: bool = False,
        delete_source: DeleteSource = DeleteSource.USER,
    ) -> dict:
        """
        Delete a Local FS record. Local FS DELETED events come from the
        connector itself (running as the connector owner), so we only allow
        the OWNER role to delete — protects against a stray batch holding a
        record_id from a different tenant.

        The connector loop passes ``User.id`` (Arango ``_key``) rather than the
        external ``userId``, so accept both — first try ``userId`` (the normal
        lookup), then fall back to fetching by ``_key`` so deletions from the
        Local FS connector don't 404 on a user/key vs. user/userId mismatch.

        Ownership is established either by a permission edge on the record or by
        being the creator of the record's connector. A full sync resets records
        it may not hold a per-record edge for, so requiring the edge alone
        aborted the whole sync (Neo4j applies no such gate to connector records).
        """
        try:
            self.logger.debug(f"📁 Deleting Local FS record {record_id}")

            user = await self.get_user_by_user_id(user_id)
            if not user:
                user = await self.http_client.get_document(
                    collection=CollectionNames.USERS.value,
                    key=user_id,
                    txn_id=transaction
                )
            if not user:
                return {
                    "success": False,
                    "code": 404,
                    "reason": f"User not found: {user_id}"
                }

            user_role = await self._check_record_permission(record_id, user.get('_key'), transaction)
            if user_role != "OWNER" and not await self._is_connector_creator(
                user, record, transaction
            ):
                return {
                    "success": False,
                    "code": 403,
                    "reason": f"Only the connector owner can delete Local FS records. Role: {user_role}"
                }

            if soft_delete:
                return await self._soft_delete_for_request(
                    record_id, record, user.get('_key'), transaction, delete_source=delete_source
                )
            return await self._execute_local_fs_record_deletion(record_id, record, transaction)

        except Exception as e:
            self.logger.error(f"❌ Failed to delete Local FS record: {str(e)}")
            return {
                "success": False,
                "code": 500,
                "reason": f"Local FS record deletion failed: {str(e)}"
            }

    async def _is_connector_creator(
        self,
        user: dict,
        record: dict,
        transaction: str | None = None
    ) -> bool:
        """True when this user created the connector the record belongs to.

        Keeps the cross-tenant guard: a batch holding a record id from another
        tenant still fails, because that record's connector has a different
        creator.
        """
        connector_id = record.get("connectorId")
        if not connector_id:
            return False
        try:
            app_doc = await self.http_client.get_document(
                collection=CollectionNames.APPS.value,
                key=connector_id,
                txn_id=transaction
            )
        except Exception as e:
            self.logger.error(f"❌ Failed to read connector {connector_id}: {str(e)}")
            return False
        if not app_doc:
            return False
        created_by = app_doc.get("createdBy")
        if not created_by:
            return False
        return created_by in {user.get("userId"), user.get("_key")}

    async def _execute_local_fs_record_deletion(
        self,
        record_id: str,
        record: dict,
        transaction: str | None = None
    ) -> dict:
        """Delete edges + file record + main record for a Local FS record."""
        try:
            file_record = await self.http_client.get_document(
                collection=CollectionNames.FILES.value,
                key=record_id,
                txn_id=transaction
            )

            await self._delete_local_fs_edges(record_id, transaction)

            if file_record:
                await self._delete_file_record(record_id, transaction)

            await self._delete_main_record(record_id, transaction)

            self.logger.debug(f"✅ Deleted Local FS record {record_id}")

            try:
                payload = await self._create_deleted_record_event_payload(record, file_record)
                if payload:
                    payload["connectorName"] = Connectors.LOCAL_FS.value
                    payload["origin"] = OriginTypes.CONNECTOR.value
                    event_data = {
                        "eventType": "deleteRecord",
                        "topic": "record-events",
                        "payload": payload
                    }
                else:
                    event_data = None
            except Exception as e:
                self.logger.error(f"❌ Failed to create Local FS deletion event payload: {str(e)}")
                event_data = None

            return {
                "success": True,
                "record_id": record_id,
                "connector": Connectors.LOCAL_FS.value,
                "eventData": event_data
            }

        except Exception as e:
            self.logger.error(f"❌ Local FS deletion failed: {str(e)}")
            return {
                "success": False,
                "reason": f"Transaction failed: {str(e)}"
            }

    async def _delete_local_fs_edges(
        self,
        record_id: str,
        transaction: str | None = None
    ) -> None:
        """Delete edges attached to a Local FS record."""
        edge_strategies = {
            CollectionNames.IS_OF_TYPE.value: {
                "filter": "edge._from == @record_from",
                "bind_vars": {"record_from": f"records/{record_id}"},
            },
            CollectionNames.PERMISSION.value: {
                "filter": "edge._to == @record_to",
                "bind_vars": {"record_to": f"records/{record_id}"},
            },
            CollectionNames.BELONGS_TO.value: {
                "filter": "edge._from == @record_from",
                "bind_vars": {"record_from": f"records/{record_id}"},
            },
        }
        edge_strategies.update(self._enrichment_edge_strategies(record_id))

        query_template = """
        FOR edge IN @@edge_collection
            FILTER {filter}
            REMOVE edge IN @@edge_collection
            RETURN OLD
        """

        for collection, strategy in edge_strategies.items():
            try:
                query = query_template.format(filter=strategy["filter"])
                bind_vars = {"@edge_collection": collection}
                bind_vars.update(strategy["bind_vars"])
                await self.http_client.execute_aql(query, bind_vars, txn_id=transaction)
            except Exception as e:
                self.logger.error(f"Failed to delete Local FS edges from {collection}: {e}")
                raise

    async def get_key_by_external_file_id(
        self,
        external_file_id: str,
        transaction: str | None = None
    ) -> str | None:
        """
        Get internal file key using the external file ID.

        Args:
            external_file_id (str): External file ID to look up
            transaction (Optional[str]): Optional transaction ID

        Returns:
            Optional[str]: Internal file key if found, None otherwise
        """
        try:
            self.logger.debug(
                f"🚀 Retrieving internal key for external file ID {external_file_id}"
            )

            query = f"""
            FOR record IN {CollectionNames.RECORDS.value}
                FILTER record.externalRecordId == @external_file_id
                RETURN record._key
            """

            results = await self.http_client.execute_aql(
                query,
                bind_vars={"external_file_id": external_file_id},
                txn_id=transaction
            )

            if results:
                self.logger.debug(
                    f"✅ Successfully retrieved internal key for external file ID {external_file_id}"
                )
                return results[0]
            else:
                self.logger.warning(
                    f"⚠️ No internal key found for external file ID {external_file_id}"
                )
                return None

        except Exception as e:
            self.logger.error(
                f"❌ Failed to retrieve internal key for external file ID {external_file_id}: {str(e)}"
            )
            return None

